window.SIRA={"ph":[{"id":"makka","t":"المرحلة المكية","d":"من البعثة إلى الهجرة: الوحي والدعوة السرية ثم الجهر، والصبر على الأذى، والإسراء."},{"id":"madina","t":"المرحلة المدنية والغزوات","d":"من الهجرة إلى وفاته ﷺ: بناء المجتمع، وتحويل القبلة، والغزوات، والصلح والفتح، وحجة الوداع."}],"ev":[{"id":"wahy","ph":"makka","t":"بدء الوحي في غار حراء","dt":"رمضان، قبل الهجرة بنحو ثلاث عشرة سنة","s":"كان النبي ﷺ يخلو بغار حراء، فجاءه جبريل بأول ما نزل من القرآن على أشهر الأقوال: «اقرأ باسم ربك الذي خلق»، ثم فتر الوحي مدة، ثم نزل «يا أيها المدثر» وبه بدأ التكليف بالإنذار.","ay":[{"t":"اقرأ باسم ربك","r":[96,1,5],"n":"أول ما نزل على أشهر الأقوال: أمر بالقراءة باسم الله الخالق، وتنويه بالعلم والقلم."},{"t":"يا أيها المدثر","r":[74,1,7],"n":"بعد فترة الوحي: بدء الأمر بالقيام بالإنذار والتكبير والتطهر والصبر."}],"q":[{"w":"ابن كثير","bk":"ibnkathir","s":96,"ay":1,"x":"تَفْسِيرُ سُورَةِ اقْرَأْ وَهِيَ أَوَّلُ شَيْءٍ نَزَلَ مِنَ الْقُرْآنِ."}],"h":[{"t":"حديث عائشة في بدء الوحي","x":"أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم مِنَ الْوَحْىِ الرُّؤْيَا الصَّالِحَةُ فِي النَّوْمِ، فَكَانَ لاَ يَرَى رُؤْيَا إِلاَّ جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، ثُمَّ حُبِّبَ إِلَيْهِ الْخَلاَءُ، وَكَانَ يَخْلُو بِغَارِ حِرَاءٍ فَيَتَحَنَّثُ فِيهِ ـ وَهُوَ التَّعَبُّدُ ـ اللَّيَالِيَ ذَوَاتِ الْعَدَدِ قَبْلَ أَنْ يَنْزِعَ إِلَى أَهْلِهِ، وَيَتَزَوَّدُ لِذَلِكَ، ثُمَّ يَرْجِعُ إِلَى خَدِيجَةَ، فَيَتَزَوَّدُ لِمِثْلِهَا، حَتَّى جَاءَهُ الْحَقُّ وَهُوَ فِي غَارِ حِرَاءٍ، فَجَاءَهُ الْمَلَكُ فَقَالَ اقْرَأْ. قَالَ \" مَا أَنَا بِقَارِئٍ \". قَالَ \" فَأَخَذَنِي فَغَطَّنِي حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ. قُلْتُ مَا أَنَا بِقَارِئٍ. فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ. فَقُلْتُ مَا أَنَا بِقَارِئٍ. فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ، ثُمَّ أَرْسَلَنِي فَقَالَ {اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ * خَلَقَ الإِنْسَانَ مِنْ عَلَقٍ * اقْرَأْ وَرَبُّكَ الأَكْرَمُ} \". فَرَجَعَ بِهَا رَسُولُ اللَّهِ صلى الله عليه وسلم يَرْجُفُ فُؤَادُهُ، فَدَخَلَ عَلَى خَدِيجَةَ بِنْتِ خُوَيْلِدٍ رضى الله عنها فَقَالَ \" زَمِّلُونِي زَمِّلُونِي \". فَزَمَّلُوهُ حَتَّى ذَهَبَ عَنْهُ الرَّوْعُ، فَقَالَ لِخَدِيجَةَ وَأَخْبَرَهَا الْخَبَرَ \" لَقَدْ خَشِيتُ عَلَى نَفْسِي \". فَقَالَتْ خَدِيجَةُ كَلاَّ وَاللَّهِ مَا يُخْزِيكَ اللَّهُ أَبَدًا، إِنَّكَ لَتَصِلُ الرَّحِمَ، وَتَحْمِلُ الْكَلَّ، وَتَكْسِبُ الْمَعْدُومَ، وَتَقْرِي الضَّيْفَ، وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ. فَانْطَلَقَتْ بِهِ خَدِيجَةُ حَتَّى أَتَتْ بِهِ وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى ابْنَ عَمِّ خَدِيجَةَ ـ وَكَانَ امْرَأً تَنَصَّرَ فِي الْجَاهِلِيَّةِ، وَكَانَ يَكْتُبُ الْكِتَابَ الْعِبْرَانِيَّ، فَيَكْتُبُ مِنَ الإِنْجِيلِ بِالْعِبْرَانِيَّةِ مَا شَاءَ اللَّهُ أَنْ يَكْتُبَ، وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ ـ فَقَالَتْ لَهُ خَدِيجَةُ يَا ابْنَ عَمِّ اسْمَعْ مِنَ ابْنِ أَخِيكَ. فَقَالَ لَهُ وَرَقَةُ يَا ابْنَ أَخِي مَاذَا تَرَى فَأَخْبَرَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم خَبَرَ مَا رَأَى. فَقَالَ لَهُ وَرَقَةُ هَذَا النَّامُوسُ الَّذِي نَزَّلَ اللَّهُ عَلَى مُوسَى صلى الله عليه وسلم يَا لَيْتَنِي فِيهَا جَذَعًا، لَيْتَنِي أَكُونُ حَيًّا إِذْ يُخْرِجُكَ قَوْمُكَ. فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" أَوَمُخْرِجِيَّ هُمْ \". قَالَ نَعَمْ، لَمْ يَأْتِ رَجُلٌ قَطُّ بِمِثْلِ مَا جِئْتَ بِهِ إِلاَّ عُودِيَ، وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا مُؤَزَّرًا","src":[["bukhari","3"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يصف بدء الوحي بالرؤيا الصادقة ثم تحنث غار حراء ونزول جبريل، وتثبيت خديجة رضي الله عنها لرسول الله ﷺ.","te":"Aisha’s hadith on the beginning of revelation","fe":"It describes the start of revelation with true dreams, the retreat at Hira, Jibril’s coming, and Khadija’s reassurance to the Messenger ﷺ.","en":"The first revelation to the Messenger of Allah ﷺ was true dreams in sleep; then solitude became dear to him. In the cave of Hira the angel came and said \"Read\"; he answered \"I am not a reader\" — three times — then recited \"Read in the name of your Lord who created\". He returned trembling to Khadija, who reassured him: \"Allah will never disgrace you; you keep family ties, bear the burdens of others, help those in need and honour the guest.\" She took him to Waraqa ibn Nawfal, who said: this is the Namus that came to Moses."}]},{"id":"duha","ph":"makka","t":"تسلية النبي ﷺ: سورتا الضحى والشرح","dt":"في أول العهد المكي","s":"اشتكى النبي ﷺ فلم يقم الليل ليلتين أو ثلاثاً، فقالت له امرأة: إني لأرجو أن يكون شيطانك قد تركك، فنزلت سورة الضحى تطمئنه بأن ربه ما تركه وما أبغضه، وفي سورة الشرح تذكير بنعم الله عليه: شرح صدره، ووضع وزره، ورفع ذكره.","ay":[{"t":"والضحى والليل إذا سجى","r":[93,1,3],"n":"قسم بالضحى والليل على أن الله ما تركه وما أبغضه."},{"t":"ولسوف يعطيك ربك فترضى","r":[93,4,5],"n":"وعد بأن آخرته خير من أولاه، وبعطاء يرضيه."},{"t":"ألم يجدك يتيما فآوى","r":[93,6,8],"n":"تذكير بنعم الله عليه: الإيواء والهداية والإغناء."},{"t":"ألم نشرح لك صدرك","r":[94,1,4],"n":"شرح الصدر، ووضع الوزر، ورفع الذكر."}],"q":[{"w":"السعدي","bk":"saadi","s":93,"ay":1,"x":"أقسم تعالى بالنهار إذا انتشر ضياؤه؛ بالضُّحى، وبالليل {إذا سجى} وادلهمَّت ظلمته؛ على اعتناء الله برسوله - صلى الله عليه وسلم -، فقال:{ما ودَّعك ربُّك}؛ أي: ما تركك منذ اعتنى بك، ولا أهملك منذ ربَّاك ورعاك، بل لم يزل يربِّيك أكمل تربيةٍ ويُعليك درجةً بعد درجةٍ، {وما}: قلاكَ الله؛ أي: ما أبغضك منذ أحبَّك؛ فإنَّ نفي الضِّدِّ دليلٌ على ثبوت ضدِّه، والنفي المحض لا يكون مدحاً إلاَّ إذا تضمَّن ثبوت كمال. فهذه حال الرسول - صلى الله عليه وسلم - الماضية والحاضرة، أكمل حال وأتمُّها، محبَّة الله له واستمرارها وترقيته في درجات الكمال ودوام اعتناء اللَّه به"},{"w":"السعدي","bk":"saadi","s":94,"ay":1,"x":"يقول تعالى ممتنًّا على رسوله: {ألم نشرحۡ لك صدرَك}؛ أي: نوسِّعْه لشرائع الدِّين والدَّعوة إلى الله والاتِّصاف بمكارم الأخلاق والإقبال على الآخرة وتسهيل الخيرات، فلم يكن ضيِّقاً حرجاً لا يكاد ينقاد لخيرٍ ولا تكاد تجده منبسطاً، {ووضعۡنا عنك وِزۡرَك}؛ أي: ذنبك، {الذي أنقَضَ}؛ أي: أثقل {ظهركَ}؛ كما قال تعالى:{ليغفرَ لك اللهُ ما تقدَّم من ذنبِكَ وما تأخَّر}، {ورفَعۡنا لكَ ذِكۡرَك}؛ أي: أعليْنا قدرَك، وجعلنا لك الثَّناء الحسن العالي، الذي لم يصلْ إليه أحدٌ من الخلق"}],"h":[{"t":"حديث جندب في نزول الضحى","x":"اشْتَكَى رَسُولُ اللَّهِ صلى الله عليه وسلم فَلَمْ يَقُمْ لَيْلَتَيْنِ أَوْ ثَلاَثًا، فَجَاءَتِ امْرَأَةٌ فَقَالَتْ يَا مُحَمَّدُ إِنِّي لأَرْجُو أَنْ يَكُونَ شَيْطَانُكَ قَدْ تَرَكَكَ، لَمْ أَرَهُ قَرِبَكَ مُنْذُ لَيْلَتَيْنِ أَوْ ثَلاَثًا. فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ {وَالضُّحَى * وَاللَّيْلِ إِذَا سَجَى * مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى}","src":[["bukhari","4950"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي جندب بن سفيان أن النبي ﷺ اشتكى فلم يقم ليلتين أو ثلاثاً، فقالت امرأة إنها ترجو أن يكون شيطانه تركه، فأنزل الله سورة الضحى.","te":"The hadith of Jundub on the revelation of ad-Duha","fe":"Jundub ibn Sufyan reports that the Prophet ﷺ fell ill and did not rise for two or three nights; a woman said she hoped his devil had left him, so Allah revealed Surah ad-Duha.","en":"The Messenger of Allah ﷺ fell ill and did not rise for prayer for two or three nights. A woman came and said: O Muhammad, I hope your devil has left you; I have not seen him near you for two or three nights. Then Allah, the Mighty and Majestic, revealed: By the morning brightness, and by the night when it grows still, your Lord has neither forsaken you nor detested you."}]},{"id":"jahr","ph":"makka","t":"الجهر بالدعوة","dt":"قبل الهجرة بنحو عشر سنين","s":"بعد سنوات من الدعوة الخفية أُمر النبي ﷺ بإنذار عشيرته الأقربين ثم بإعلان الدعوة والصدع بها، فصعد الصفا ونادى قريشاً.","ay":[{"t":"وأنذر عشيرتك الأقربين","r":[26,214,216],"n":"أمر بإنذار الأقربين ولين الجانب للمؤمنين، والتبرؤ من العصيان."},{"t":"فاصدع بما تؤمر","r":[15,94,94],"n":"الصدع: الجهر والإظهار، مع الإعراض عن المشركين."}],"q":[],"h":[{"t":"نداء الصفا","x":"لَمَّا نَزَلَتْ {وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ} صَعِدَ النَّبِيُّ صلى الله عليه وسلم عَلَى الصَّفَا فَجَعَلَ يُنَادِي \" يَا بَنِي فِهْرٍ، يَا بَنِي عَدِيٍّ \". لِبُطُونِ قُرَيْشٍ حَتَّى اجْتَمَعُوا، فَجَعَلَ الرَّجُلُ إِذَا لَمْ يَسْتَطِعْ أَنْ يَخْرُجَ أَرْسَلَ رَسُولاً لِيَنْظُرَ مَا هُوَ، فَجَاءَ أَبُو لَهَبٍ وَقُرَيْشٌ فَقَالَ \" أَرَأَيْتَكُمْ لَوْ أَخْبَرْتُكُمْ أَنَّ خَيْلاً بِالْوَادِي تُرِيدُ أَنْ تُغِيرَ عَلَيْكُمْ، أَكُنْتُمْ مُصَدِّقِيَّ \". قَالُوا نَعَمْ، مَا جَرَّبْنَا عَلَيْكَ إِلاَّ صِدْقًا. قَالَ \" فَإِنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ \". فَقَالَ أَبُو لَهَبٍ تَبًّا لَكَ سَائِرَ الْيَوْمِ، أَلِهَذَا جَمَعْتَنَا فَنَزَلَتْ {تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ * مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ","src":[["bukhari","4770"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي ابن عباس أن النبي ﷺ صعد الصفا ونادى بطون قريش وسألهم: لو أخبرتكم أن خيلاً تريد أن تغير عليكم أكنتم مصدقي؟ قالوا: ما جربنا عليك إلا صدقاً.","te":"The call at as-Safa","fe":"Ibn Abbas reports that the Prophet ﷺ climbed as-Safa, called the clans of Quraysh and asked: if I told you that cavalry is about to raid you, would you believe me? They said: we have found nothing but truth from you.","en":"When \"Warn your nearest kin\" was revealed, the Prophet ﷺ climbed as-Safa and called \"O Banu Fihr, O Banu Adi\" until they gathered. He said: if I told you that cavalry in the valley intends to raid you, would you believe me? They said: yes. He said: I am a warner to you before a severe punishment. Abu Lahab said: ruin on you, did you gather us for this? Then \"Perish the hands of Abu Lahab\" was revealed."}]},{"id":"abasa","ph":"makka","t":"عتاب «عبس وتولى» في ابن أم مكتوم","dt":"في العهد المكي","s":"جاء رجل أعمى من المؤمنين هو ابن أم مكتوم يسأل النبي ﷺ ويتعلم منه، وعنده رجل من عظماء المشركين يرجو هدايته، فأعرض عن الأعمى وأقبل على الآخر، فنزل العتاب اللطيف في سورة عبس ليبقى أصلاً في العناية بالطالب الصادق ولو كان ضعيفاً فقيراً.","ay":[{"t":"عبس وتولى أن جاءه الأعمى","r":[80,1,4],"n":"عتاب لطيف: ما يدريك لعله يتزكى أو يتذكر فتنفعه الذكرى."},{"t":"أما من استغنى فأنت له تصدى","r":[80,5,10],"n":"ليس عليه إلا البلاغ، والمقبل الخاشي أولى بالإقبال."}],"q":[{"w":"السعدي","bk":"saadi","s":80,"ay":1,"x":"سببُ نزول هذه الآيات الكريمات أنَّه جاء رجلٌ من المؤمنين أعمى يسألُ النبيَّ - صلى الله عليه وسلم - ويتعلَّم منه، وجاءهُ رجلٌ من الأغنياء، وكان - صلى الله عليه وسلم - حريصاً على هداية الخلق، فمال - صلى الله عليه وسلم - وأصغى إلى الغنيِّ وصدَّ عن الأعمى الفقير؛ رجاءً لهداية ذلك الغنيِّ وطمعاً في تزكيته"},{"w":"ابن كثير","bk":"ibnkathir","s":80,"ay":1,"x":"ذَكَرَ غيرُ وَاحِدٍ مِنَ الْمُفَسِّرِينَ أَنَّ رَسُولَ اللَّهِ ﷺ كَانَ يَوْمًا يخاطبُ بَعْضَ عُظَمَاءِ قُرَيْشٍ، وَقَدْ طَمع فِي إِسْلَامِهِ، فَبَيْنَمَا هُوَ يُخَاطِبُهُ وَيُنَاجِيهُ إِذْ أَقْبَلَ ابنُ أُمِّ مَكْتُومٍ-وَكَانَ مِمَّنْ أَسْلَمَ قَدِيمًا-فَجَعَلَ يَسْأَلُ رَسُولَ اللَّهِ ﷺ عَنْ شَيْءٍ وَيُلِحُّ عَلَيْهِ، وودَّ النَّبِيُّ ﷺ أَنْ لَوْ كَفَّ سَاعَتَهُ تِلْكَ لِيَتَمَكَّنَ مِنْ مُخَاطَبَةِ ذَلِكَ الرَّجُلِ؛ طَمَعًا وَرَغْبَةً فِي هِدَايَتِهِ"}],"h":[{"t":"حديث عائشة في نزول «عبس»","x":"قَالَتْ أُنْزِلَ : ( عبَسَ وَتَوَلَّى ) فِي ابْنِ أُمِّ مَكْتُومٍ الأَعْمَى أَتَى رَسُولَ اللَّهِ صلى الله عليه وسلم فَجَعَلَ يَقُولُ يَا رَسُولَ اللَّهِ أَرْشِدْنِي وَعِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم رَجُلٌ مِنْ عُظَمَاءِ الْمُشْرِكِينَ فَجَعَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُعْرِضُ عَنْهُ وَيُقْبِلُ عَلَى الآخَرِ وَيَقُولُ أَتَرَى بِمَا أَقُولُ بَأْسًا فَيُقَالُ لاَ . فَفِي هَذَا أُنْزِلَ","src":[["tirmidhi","3331"]],"gr":"","dg":"الألباني: إسناده صحيح؛ أحمد شاكر: إسناده صحيح؛ زبير علي زئي: إسناده صحيح","f":"تروي عائشة أن سورة عبس نزلت في ابن أم مكتوم الأعمى حين جاء يطلب الإرشاد وعند النبي ﷺ رجل من عظماء المشركين.","te":"The hadith of ‘A’ishah on the revelation of ‘Abasa","fe":"‘A’ishah reports that Surah ‘Abasa was revealed about the blind Ibn Umm Maktum when he came seeking guidance while a leader of the idolaters was with the Prophet ﷺ.","en":"‘A’ishah said: (He frowned and turned away) was revealed about Ibn Umm Maktum, the blind man. He came to the Messenger of Allah ﷺ and kept saying: O Messenger of Allah, guide me — while one of the leaders of the idolaters was with the Messenger of Allah ﷺ. The Messenger of Allah ﷺ turned away from him and faced the other, asking him: Do you see any harm in what I say? He said: No. It was about this that it was revealed."}]},{"id":"qamar","ph":"makka","t":"انشقاق القمر","dt":"في العهد المكي، قبل الهجرة","s":"طلب مشركو مكة من النبي ﷺ آية، فأراهم الله القمر شقتين حتى رأوا حراء بينهما، فقال لهم: «اشهدوا». ومع ذلك أعرضوا وقالوا: سحر مستمر، وفي ذلك تنبيه على أن العناد لا تنفع معه الآيات.","ay":[{"t":"اقتربت الساعة وانشق القمر","r":[54,1,3],"n":"اقتراب الساعة، وآية انشقاق القمر، وإعراض المكذبين عنها."}],"q":[{"w":"السعدي","bk":"saadi","s":54,"ay":1,"x":"فمن أعظم الآياتِ الدالَّة على صحَّة ما جاء به محمد بن عبد الله - صلى الله عليه وسلم - أنَّه لما طلب منه المكذِّبون أن يُرِيَهم من خوارق العادات ما يدلُّ على صحَّة ما جاء به وصدقه ؛ أشار - صلى الله عليه وسلم - إلى القمر، فانشقَّ بإذن الله فلقتين؛ فلقةً على جبل أبي قُبيس، وفلقةً على جبل قعيقعان، والمشركون وغيرهم يشاهدون هذه الآية العظيمة الكائنة في العالم العلويِّ، التي لا يقدر الخلقُ على التمويه بها والتخييل، فشاهدوا أمراً ما رأوا مثلَه، بل ولم يسمعوا أنَّه جرى لأحدٍ من المرسلين قبلَه نظيره، فانبهروا لذلك، ولم يدخُل الإيمانُ في قلوبهم، ولم يردِ الله بهم خيراً، ففزعوا إلى بهتهم وطغيانهم، وقالوا: سحرنا محمدٌ! ولكنَّ علامة ذلك أنكم تسألون من وَرَدَ عليكم من السفر؛ فإنَّه إن قدر على سحركم؛ لم يقدِرْ أن يسحرَ مَن ليس مشاهداً مثلكم! فسألوا كلَّ من قدم، فأخبروهم بوقوع ذلك، فقالوا:{سحرٌ مستمرٌّ}! سحرنا محمدٌ وسحر غيرنا"}],"h":[{"t":"حديث ابن مسعود في انشقاق القمر","x":"انْشَقَّ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم شِقَّتَيْنِ فَقَالَ النَّبِيُّ صلى الله عليه وسلم اشْهَدُوا","src":[["bukhari","3636"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يخبر ابن مسعود أن القمر انشق في عهد النبي ﷺ شقتين، وأن النبي ﷺ أمر الحاضرين بالشهادة على الآية.","te":"The hadith of Ibn Mas‘ud on the splitting of the moon","fe":"Ibn Mas‘ud reports that the moon split into two halves in the time of the Prophet ﷺ, who told those present to bear witness to the sign.","en":"The moon was split into two halves in the time of the Messenger of Allah ﷺ, and the Prophet ﷺ said: “Bear witness.”"},{"t":"حديث أنس في انشقاق القمر","x":"أَنَّ أَهْلَ، مَكَّةَ سَأَلُوا رَسُولَ اللَّهِ صلى الله عليه وسلم أَنْ يُرِيَهُمْ آيَةً، فَأَرَاهُمُ الْقَمَرَ شِقَّتَيْنِ، حَتَّى رَأَوْا حِرَاءً بَيْنَهُمَا","src":[["bukhari","3868"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي أنس أن أهل مكة سألوا النبي ﷺ آية، فأراهم القمر شقتين حتى رأوا جبل حراء بينهما.","te":"The hadith of Anas on the splitting of the moon","fe":"Anas reports that the people of Makkah asked the Prophet ﷺ for a sign and he showed them the moon in two halves until they saw Mount Hira between them.","en":"The people of Makkah asked the Messenger of Allah ﷺ to show them a sign, so he showed them the moon split in two, until they saw Hira between the two halves."}]},{"id":"jinn","ph":"makka","t":"استماع الجن للقرآن","dt":"في العهد المكي، ببطن نخلة قبل الهجرة","s":"حيل بين الشياطين وبين خبر السماء وأُرسلت عليهم الشهب، فبحثوا عن السبب حتى وجدوا النبي ﷺ يصلي الفجر بأصحابه في نخلة، فاستمعوا القرآن وآمنوا ورجعوا إلى قومهم منذرين، فأنزل الله خبرهم على نبيه ﷺ.","ay":[{"t":"قل أوحي إلي أنه استمع نفر من الجن","r":[72,1,2],"n":"خبر الجن وإيمانهم بالقرآن بعد سماعه."},{"t":"وإذ صرفنا إليك نفرا من الجن يستمعون القرآن","r":[46,29,32],"n":"انصرافهم إلى النبي ﷺ واستماعهم وإنذارهم لقومهم."}],"q":[{"w":"السعدي","bk":"saadi","s":72,"ay":1,"x":"أي: {قل}: يا أيُّها الرسول للناس، {أوحِيَ إليَّ أنَّه استمع نفرٌ من الجنِّ}: صرفهم الله إلى رسوله لسماع آياته؛ لتقوم عليهم الحجَّة وتتمَّ عليهم النعمة ويكونوا منذِرين لقومهم"},{"w":"السعدي","bk":"saadi","s":46,"ay":29,"x":"كان الله تعالى قد أرسل رسولَه محمداً - صلى الله عليه وسلم - إلى الخلق إنسهم وجنهم، وكان لا بدَّ من إبلاغ الجميع لدعوة النبوَّة والرسالة؛ فالإنس يمكنه عليه الصلاة والسلام دعوتُهم وإنذارُهم، وأمَّا الجنُّ؛ فصَرَفَهم الله إليه بقدرته وأرسل إليه {نفراً من الجنِّ يستمعونَ القرآن فلمَّا حَضَروه قالوا أنصِتوا}؛ أي: وصَّى بعضُهم بعضاً بذلك، {فلما قُضِيَ}: وقد وَعَوْه وأثَّر ذلك فيهم، {ولَّوۡا إلى قومِهِم منذِرين}: نصحاً منهم لهم، وإقامة لحجَّة الله عليهم، وقيَّضهم الله معونةً لرسوله - صلى الله عليه وسلم - في نشر دعوتِهِ في الجنِّ"}],"h":[{"t":"حديث ابن عباس في استماع الجن","x":"انْطَلَقَ النَّبِيُّ صلى الله عليه وسلم فِي طَائِفَةٍ مِنْ أَصْحَابِهِ عَامِدِينَ إِلَى سُوقِ عُكَاظٍ، وَقَدْ حِيلَ بَيْنَ الشَّيَاطِينِ وَبَيْنَ خَبَرِ السَّمَاءِ، وَأُرْسِلَتْ عَلَيْهِمُ الشُّهُبُ، فَرَجَعَتِ الشَّيَاطِينُ إِلَى قَوْمِهِمْ. فَقَالُوا مَا لَكُمْ فَقَالُوا حِيلَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ، وَأُرْسِلَتْ عَلَيْنَا الشُّهُبُ. قَالُوا مَا حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ إِلاَّ شَىْءٌ حَدَثَ، فَاضْرِبُوا مَشَارِقَ الأَرْضِ وَمَغَارِبَهَا، فَانْظُرُوا مَا هَذَا الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ فَانْصَرَفَ أُولَئِكَ الَّذِينَ تَوَجَّهُوا نَحْوَ تِهَامَةَ إِلَى النَّبِيِّ صلى الله عليه وسلم وَهْوَ بِنَخْلَةَ، عَامِدِينَ إِلَى سُوقِ عُكَاظٍ وَهْوَ يُصَلِّي بِأَصْحَابِهِ صَلاَةَ الْفَجْرِ، فَلَمَّا سَمِعُوا الْقُرْآنَ اسْتَمَعُوا لَهُ فَقَالُوا هَذَا وَاللَّهِ الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ. فَهُنَالِكَ حِينَ رَجَعُوا إِلَى قَوْمِهِمْ وَقَالُوا يَا قَوْمَنَا {إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا * يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ وَلَنْ نُشْرِكَ بِرَبِّنَا أَحَدًا} فَأَنْزَلَ اللَّهُ عَلَى نَبِيِّهِ صلى الله عليه وسلم {قُلْ أُوحِيَ إِلَىَّ} وَإِنَّمَا أُوحِيَ إِلَيْهِ قَوْلُ الْجِنِّ","src":[["bukhari","773"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي ابن عباس أن الجن لما حيل بينهم وبين خبر السماء بحثوا عن السبب فسمعوا النبي ﷺ يقرأ في صلاة الفجر ببطن نخلة، فآمنوا ونزل خبرهم في سورة الجن.","te":"The hadith of Ibn ‘Abbas on the jinn listening","fe":"Ibn ‘Abbas reports that when the jinn were barred from the news of heaven they searched for the cause, heard the Prophet ﷺ reciting in the dawn prayer at Nakhlah, believed, and their story came down in Surah al-Jinn.","en":"The Prophet ﷺ set out with a group of his Companions heading for the market of ‘Ukaz. The devils had been barred from the news of heaven and shooting stars were sent at them, so they returned to their people. They said: What is wrong with you? They said: We have been barred from the news of heaven and shooting stars were sent at us. They said: Only something new has come between you and the news of heaven, so travel the east and west of the earth and see what has come between you and it. Those who headed for Tihamah came upon the Prophet ﷺ at Nakhlah, on his way to the market of ‘Ukaz, while he was leading his Companions in the dawn prayer. When they heard the Qur’an they listened to it and said: This, by Allah, is what has come between you and the news of heaven. Then they returned to their people and said: O our people, we have heard a wondrous Qur’an which guides to the right course, so we have believed in it and will never associate anyone with our Lord. Then Allah revealed to His Prophet ﷺ: Say, it has been revealed to me — and what was revealed to him was the speech of the jinn."}]},{"id":"isra","ph":"makka","t":"الإسراء والمعراج","dt":"قبل الهجرة، واختُلف في تعيين وقته","s":"أُسري بالنبي ﷺ من المسجد الحرام إلى المسجد الأقصى ثم عُرج به إلى السماوات، وفُرضت فيها الصلوات الخمس.","ay":[{"t":"سبحان الذي أسرى بعبده","r":[17,1,1],"n":"نص الإسراء: تنزيه لله وبيان لقدرته، وتشريف للنبي ﷺ بعبوديته."}],"q":[{"w":"القرطبي","bk":"qurtubi","s":17,"ay":1,"x":"وَلَا خِلَافَ بَيْنَ أَهْلِ الْعِلْمِ وَجَمَاعَةِ أَهْلِ السِّيَرِ أَنَّ الصَّلَاةَ إِنَّمَا فُرِضَتْ عَلَى النَّبِيِّ ﷺ بِمَكَّةَ فِي حِينِ الْإِسْرَاءِ حِينَ عُرِجَ بِهِ إِلَى السَّمَاءِ."}],"h":[]},{"id":"hijra","ph":"madina","t":"الهجرة والغار","dt":"ربيع الأول، السنة الأولى للهجرة","s":"ائتمرت قريش على النبي ﷺ فنجّاه الله، وخرج مع أبي بكر الصديق رضي الله عنه واختبآ في غار ثور ثم وصلا المدينة.","ay":[{"t":"وإذ يمكر بك الذين كفروا","r":[8,30,30],"n":"مكر قريش بالنبي ﷺ بين الحبس والقتل والإخراج، ومكر الله خير."},{"t":"إذ هما في الغار","r":[9,40,40],"n":"الغار: صاحبه أبو بكر، وسكينة الله عليه: «لا تحزن إن الله معنا»."}],"q":[],"h":[{"t":"أبو بكر في الغار","x":"كُنْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم فِي الْغَارِ، فَرَأَيْتُ آثَارَ الْمُشْرِكِينَ قُلْتُ يَا رَسُولَ اللَّهِ، لَوْ أَنَّ أَحَدَهُمْ رَفَعَ قَدَمَهُ رَآنَا. قَالَ \" مَا ظَنُّكَ بِاثْنَيْنِ اللَّهُ ثَالِثُهُمَا \"","src":[["bukhari","4663"]],"gr":"صحيح: رواه البخاري","dg":"","f":"قال أبو بكر: لو أن أحدهم رفع قدمه رآنا، فقال النبي ﷺ: ما ظنك باثنين الله ثالثهما.","te":"Abu Bakr in the cave","fe":"Abu Bakr said: if one of them raised his foot he would see us; the Prophet ﷺ said: what do you think of two whose third is Allah?","en":"Abu Bakr said: I was with the Prophet ﷺ in the cave and saw the footprints of the idolaters; I said: O Messenger of Allah, if one of them raised his foot he would see us. He said: what do you think, Abu Bakr, of two whose third is Allah?"}]},{"id":"qibla","ph":"madina","t":"تحويل القبلة","dt":"السنة الثانية للهجرة بعد أشهر من القدوم","s":"صلّى النبي ﷺ إلى بيت المقدس نحو ستة عشر شهراً وكان يحب أن يتجه إلى الكعبة، فنزل الأمر باستقبال المسجد الحرام.","ay":[{"t":"سيقول السفهاء","r":[2,142,142],"n":"إخبار بما سيقوله المعترضون على تحويل القبلة، وجوابه: لله المشرق والمغرب."},{"t":"فولّ وجهك شطر المسجد الحرام","r":[2,144,144],"n":"تحويل القبلة: قد نرى تقلب وجهك في السماء، فلنولينك قبلة ترضاها."}],"q":[],"h":[{"t":"البراء: حادثة تحويل القبلة","x":"كَانَ أَوَّلَ مَا قَدِمَ الْمَدِينَةَ نَزَلَ عَلَى أَجْدَادِهِ ـ أَوْ قَالَ أَخْوَالِهِ ـ مِنَ الأَنْصَارِ، وَأَنَّهُ صَلَّى قِبَلَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا، أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ الْبَيْتِ، وَأَنَّهُ صَلَّى أَوَّلَ صَلاَةٍ صَلاَّهَا صَلاَةَ الْعَصْرِ، وَصَلَّى مَعَهُ قَوْمٌ، فَخَرَجَ رَجُلٌ مِمَّنْ صَلَّى مَعَهُ، فَمَرَّ عَلَى أَهْلِ مَسْجِدٍ، وَهُمْ رَاكِعُونَ فَقَالَ أَشْهَدُ بِاللَّهِ لَقَدْ صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم قِبَلَ مَكَّةَ، فَدَارُوا كَمَا هُمْ قِبَلَ الْبَيْتِ، وَكَانَتِ الْيَهُودُ قَدْ أَعْجَبَهُمْ إِذْ كَانَ يُصَلِّي قِبَلَ بَيْتِ الْمَقْدِسِ، وَأَهْلُ الْكِتَابِ، فَلَمَّا وَلَّى وَجْهَهُ قِبَلَ الْبَيْتِ أَنْكَرُوا ذَلِكَ","src":[["bukhari","40"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي البراء أن النبي ﷺ صلى إلى بيت المقدس ستة عشر أو سبعة عشر شهراً، ثم وُجّه إلى الكعبة فداروا كما هم في الصلاة.","te":"Al-Bara’: the change of the qibla","fe":"Al-Bara’ reports that the Prophet ﷺ prayed toward Jerusalem for sixteen or seventeen months, then was directed to the Kaaba, and the worshippers turned as they were during prayer.","en":"The Prophet ﷺ prayed toward Jerusalem for sixteen or seventeen months, though he loved that his qibla be toward the House. A man who had prayed with him passed by a mosque where people were bowing and said: I testify that I prayed with the Messenger of Allah ﷺ toward Mecca; so they turned just as they were toward the House."}]},{"id":"jumua","ph":"madina","t":"حادثة الانفضاض إلى التجارة يوم الجمعة","dt":"في المدينة، دون تحديد سنة في الصحيح","s":"بينما كان النبي ﷺ يخطب يوم الجمعة، قدمت عير من الشام تحمل طعاماً، فانصرف إليها أكثر من في المسجد ولم يبق معه إلا اثنا عشر رجلاً، فنزلت الآية تعاتبهم وتؤكد أن ما عند الله خير من اللهو ومن التجارة.","ay":[{"t":"إذا نودي للصلاة من يوم الجمعة فاسعوا إلى ذكر الله","r":[62,9,10],"n":"الأمر بالسعي إلى الجمعة وترك البيع، ثم الانتشار في الأرض بعد الصلاة."},{"t":"وإذا رأوا تجارة أو لهوا انفضوا إليها","r":[62,11,11],"n":"عتاب على الانصراف عن الخطبة، وبيان أن ما عند الله خير."}],"q":[{"w":"السعدي","bk":"saadi","s":62,"ay":11,"x":"أي: خرجوا من المسجد حرصاً على ذلك اللهو وتلك التجارة وتركوا الخير، {وتركوكَ قائماً}: تخطُبُ الناس، وذلك في يوم الجمعة، بينما النبيُّ - صلى الله عليه وسلم - يخطب الناس؛ إذ قَدِمَ المدينةَ عيرٌ تحمل تجارةً، فلمَّا سمع الناس بها وهم في المسجد؛ انفضُّوا من المسجد ، وتركوا النبيَّ - صلى الله عليه وسلم - يخطبُ استعجالاً لما لا ينبغي أن يُستعجل له وترك أدب"},{"w":"ابن كثير","bk":"ibnkathir","s":62,"ay":11,"x":"يُعَاتِبُ تَبَارَكَ وَتَعَالَى عَلَى مَا كَانَ وَقَعَ مِنْ الِانْصِرَافِ عَنِ الْخُطْبَةِ يَوْمَ الْجُمُعَةِ إِلَى التِّجَارَةِ الَّتِي قَدِمَتِ الْمَدِينَةَ يَوْمَئِذٍ، فَقَالَ تَعَالَى: ﴿وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا﴾ أَيْ: عَلَى الْمِنْبَرِ تَخْطُبُ"}],"h":[{"t":"حديث جابر في الانفضاض إلى العير","x":"بَيْنَمَا نَحْنُ نُصَلِّي مَعَ النَّبِيِّ صلى الله عليه وسلم إِذْ أَقْبَلَتْ عِيرٌ تَحْمِلُ طَعَامًا، فَالْتَفَتُوا إِلَيْهَا حَتَّى مَا بَقِيَ مَعَ النَّبِيِّ صلى الله عليه وسلم إِلاَّ اثْنَا عَشَرَ رَجُلاً، فَنَزَلَتْ هَذِهِ الآيَةُ {وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا}","src":[["bukhari","936"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي جابر أن الناس لما أقبلت العير تركوا النبي ﷺ قائماً على المنبر حتى لم يبق معه إلا اثنا عشر رجلاً.","te":"The hadith of Jabir on leaving for the caravan","fe":"Jabir reports that when the caravan arrived the people left the Prophet ﷺ standing on the pulpit until only twelve men remained with him.","en":"While we were praying with the Prophet ﷺ, a caravan carrying food arrived. The people turned to it until only twelve men remained with the Prophet ﷺ, and then this verse was revealed: (But when they saw a transaction or a diversion, they rushed to it and left you standing)."}]},{"id":"badr","ph":"madina","t":"غزوة بدر الكبرى","dt":"17 رمضان، السنة الثانية للهجرة","s":"التقى نحو ثلاثمائة وبضعة عشر مسلماً بجيش قريش في بدر، فنصرهم الله مع قلة عددهم وأمدّهم بالملائكة، وكانت أول معركة فاصلة بين الإيمان والكفر.","ay":[{"t":"وإذ يعدكم الله إحدى الطائفتين","r":[8,7,7],"n":"وعد الله بإحدى الطائفتين: العير أو النفير، وإرادته إحقاق الحق."},{"t":"إذ تستغيثون ربكم","r":[8,9,9],"n":"استغاثة النبي ﷺ والمسلمين، فأمدّهم الله بألف من الملائكة مردفين."},{"t":"وما رميت إذ رميت","r":[8,17,17],"n":"أثر النصر من الله لا من الأسباب وحدها: «ولكن الله رمى»."},{"t":"ولقد نصركم الله ببدر","r":[3,123,123],"n":"تذكير بنصر بدر وأنهم أذلة، لعلهم يشكرون."}],"q":[{"w":"ابن كثير","bk":"ibnkathir","s":8,"ay":17,"x":"قَالَ عَلِيُّ بْنُ أَبِي طَلْحَةَ، عَنِ ابْنِ عَبَّاسٍ: رَفَعَ رَسُولُ اللَّهِ ﷺ يَدَيْهِ -يَعْنِي يَوْمَ بَدْرٍ -فَقَالَ: \" يَا رَبِّ إِنْ تُهْلِكْ هَذِهِ الْعِصَابَةَ، فَلَنْ تُعْبَدَ فِي الْأَرْضِ أَبَدًا\"."}],"h":[{"t":"دعاء النبي ﷺ يوم بدر","x":"لَمَّا كَانَ يَوْمُ بَدْرٍ نَظَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى الْمُشْرِكِينَ وَهُمْ أَلْفٌ وَأَصْحَابُهُ ثَلاَثُمِائَةٍ وَتِسْعَةَ عَشَرَ رَجُلاً فَاسْتَقْبَلَ نَبِيُّ اللَّهِ صلى الله عليه وسلم الْقِبْلَةَ ثُمَّ مَدَّ يَدَيْهِ فَجَعَلَ يَهْتِفُ بِرَبِّهِ \" اللَّهُمَّ أَنْجِزْ لِي مَا وَعَدْتَنِي اللَّهُمَّ آتِ مَا وَعَدْتَنِي اللَّهُمَّ إِنْ تَهْلِكْ هَذِهِ الْعِصَابَةُ مِنْ أَهْلِ الإِسْلاَمِ لاَ تُعْبَدْ فِي الأَرْضِ \". فَمَازَالَ يَهْتِفُ بِرَبِّهِ مَادًّا يَدَيْهِ مُسْتَقْبِلَ الْقِبْلَةِ حَتَّى سَقَطَ رِدَاؤُهُ عَنْ مَنْكِبَيْهِ فَأَتَاهُ أَبُو بَكْرٍ فَأَخَذَ رِدَاءَهُ فَأَلْقَاهُ عَلَى مَنْكِبَيْهِ ثُمَّ الْتَزَمَهُ مِنْ وَرَائِهِ. وَقَالَ يَا نَبِيَّ اللَّهِ كَذَاكَ مُنَاشَدَتُكَ رَبَّكَ فَإِنَّهُ سَيُنْجِزُ لَكَ مَا وَعَدَكَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ { إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنَ الْمَلاَئِكَةِ مُرْدِفِينَ} فَأَمَدَّهُ اللَّهُ بِالْمَلاَئِكَةِ","src":[["muslim","1763"]],"gr":"صحيح: رواه مسلم","dg":"","f":"عدد المشركين ألف والمسلمين ثلاثمائة وتسعة عشر، فاستقبل النبي ﷺ القبلة ومدّ يديه يدعو ربه حتى سقط رداؤه، فأمدّه الله بالملائكة.","te":"The Prophet’s supplication on the day of Badr","fe":"The idolaters were a thousand and the Muslims 319; the Prophet ﷺ faced the qibla, stretched out his hands calling on his Lord until his cloak fell, and Allah supported him with angels.","en":"On the day of Badr the Prophet ﷺ looked at the idolaters, who were a thousand, while his Companions were 319. He faced the qibla and stretched out his hands, calling: O Allah, fulfil what You promised me; if this small band perishes, You will not be worshipped on earth. He kept calling until his cloak fell from his shoulders; Abu Bakr put it back and said: that is enough, O Prophet of Allah, He will fulfil what He promised you. Then Allah revealed \"When you sought help from your Lord, and He answered you: I will reinforce you with a thousand angels\"."}]},{"id":"uhud","ph":"madina","t":"غزوة أحد","dt":"شوال، السنة الثالثة للهجرة","s":"خرجت قريش ثأراً ليوم بدر، فأقام النبي ﷺ الرماة على جبل الرماة وأمرهم ألا يتركوا مواقعهم، ثم نزل بعضهم طلباً للغنيمة فاختلّت الصفوف وأصاب المسلمين ما أصابهم؛ ونزلت آيات كثيرة في سورة آل عمران تعالج دروس الغزوة.","ay":[{"t":"وإذ غدوت من أهلك","r":[3,121,121],"n":"تذكير بخروج النبي ﷺ لتبوئة المؤمنين مقاعد للقتال."},{"t":"ولا تهنوا ولا تحزنوا","r":[3,139,140],"n":"تثبيت للمؤمنين بعد الهزيمة: إن كنتم مؤمنين فأنتم الأعلون، وتلك الأيام نداولها بين الناس."},{"t":"ولقد صدقكم الله وعده","r":[3,152,152],"n":"بيان أثر ترك الموقع وطلب الدنيا بعد نصر أول الأمر."},{"t":"ثم أنزل عليكم من بعد الغم أمنة نعاسا","r":[3,154,154],"n":"النعاس نعمة سكينة على من ثبت في المعركة."}],"q":[{"w":"القرطبي","bk":"qurtubi","s":3,"ay":154,"x":"تَفَضَّلَ اللَّهُ تَعَالَى عَلَى الْمُؤْمِنِينَ بَعْدَ هَذِهِ الْغُمُومِ فِي يَوْمِ أُحُدٍ بِالنُّعَاسِ حَتَّى نَامَ أَكْثَرُهُمْ، وَإِنَّمَا يَنْعَسُ مَنْ يَأْمَنُ وَالْخَائِفُ لَا يَنَامُ."}],"h":[{"t":"البراء: الرماة وأبو سفيان يوم أحد","x":"لَقِينَا الْمُشْرِكِينَ يَوْمَئِذٍ، وَأَجْلَسَ النَّبِيُّ صلى الله عليه وسلم جَيْشًا مِنَ الرُّمَاةِ، وَأَمَّرَ عَلَيْهِمْ عَبْدَ اللَّهِ وَقَالَ \" لاَ تَبْرَحُوا، إِنْ رَأَيْتُمُونَا ظَهَرْنَا عَلَيْهِمْ فَلاَ تَبْرَحُوا وَإِنْ رَأَيْتُمُوهُمْ ظَهَرُوا عَلَيْنَا فَلاَ تُعِينُونَا \". فَلَمَّا لَقِينَا هَرَبُوا حَتَّى رَأَيْتُ النِّسَاءَ يَشْتَدِدْنَ فِي الْجَبَلِ، رَفَعْنَ عَنْ سُوقِهِنَّ قَدْ بَدَتْ خَلاَخِلُهُنَّ، فَأَخَذُوا يَقُولُونَ الْغَنِيمَةَ الْغَنِيمَةَ. فَقَالَ عَبْدُ اللَّهِ عَهِدَ إِلَىَّ النَّبِيُّ صلى الله عليه وسلم أَنْ لاَ تَبْرَحُوا. فَأَبَوْا، فَلَمَّا أَبَوْا صُرِفَ وُجُوهُهُمْ، فَأُصِيبَ سَبْعُونَ قَتِيلاً، وَأَشْرَفَ أَبُو سُفْيَانَ فَقَالَ أَفِي الْقَوْمِ مُحَمَّدٌ فَقَالَ \" لاَ تُجِيبُوهُ \". فَقَالَ أَفِي الْقَوْمِ ابْنُ أَبِي قُحَافَةَ قَالَ \" لاَ تُجِيبُوهُ \". فَقَالَ أَفِي الْقَوْمِ ابْنُ الْخَطَّابِ فَقَالَ إِنَّ هَؤُلاَءِ قُتِلُوا، فَلَوْ كَانُوا أَحْيَاءً لأَجَابُوا، فَلَمْ يَمْلِكْ عُمَرُ نَفْسَهُ فَقَالَ كَذَبْتَ يَا عَدُوَّ اللَّهِ، أَبْقَى اللَّهُ عَلَيْكَ مَا يُخْزِيكَ. قَالَ أَبُو سُفْيَانَ أُعْلُ هُبَلْ. فَقَالَ النَّبِيُّ صلى الله عليه وسلم \" أَجِيبُوهُ \". قَالُوا مَا نَقُولُ قَالَ \" قُولُوا اللَّهُ أَعْلَى وَأَجَلُّ \". قَالَ أَبُو سُفْيَانَ لَنَا الْعُزَّى وَلاَ عُزَّى لَكُمْ. فَقَالَ النَّبِيُّ صلى الله عليه وسلم \" أَجِيبُوهُ \". قَالُوا مَا نَقُولُ قَالَ \" قُولُوا اللَّهُ مَوْلاَنَا وَلاَ مَوْلَى لَكُمْ \". قَالَ أَبُو سُفْيَانَ يَوْمٌ بِيَوْمِ بَدْرٍ، وَالْحَرْبُ سِجَالٌ، وَتَجِدُونَ مُثْلَةً لَمْ آمُرْ بِهَا وَلَمْ تَسُؤْنِي","src":[["bukhari","4043"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي البراء كيف أجلس النبي ﷺ الرماة وأمرهم بالثبات، ثم مخالفتهم لطلب الغنيمة وما أصاب المسلمين.","te":"Al-Bara’: the archers and Abu Sufyan at Uhud","fe":"Al-Bara’ tells how the Prophet ﷺ stationed the archers and ordered them to hold, then their departure for spoils and what befell the Muslims.","en":"On the day we met the idolaters, the Prophet ﷺ stationed a force of archers, appointed Abdullah over them and said: do not leave your place — if you see us defeat them, do not leave, and if you see them defeat us, do not help us. When the enemy fled, they started saying: the spoils! Abdullah said: the Prophet ﷺ ordered us not to leave. They refused, so their faces were turned away and seventy were killed."}]},{"id":"hamra","ph":"madina","t":"حمراء الأسد: «حسبنا الله ونعم الوكيل»","dt":"شوال، السنة الثالثة للهجرة، بعد أحد","s":"بعد أحد خشي النبي ﷺ أن يرجع المشركون إلى المدينة، فندب أصحابه إلى اللحاق بهم وفيهم الجراح، فاستجابوا، وبلغوا حمراء الأسد، وخُوّفوا بجموع قريش فقالوا: حسبنا الله ونعم الوكيل، فانقلبوا بنعمة من الله وفضل لم يمسسهم سوء.","ay":[{"t":"الذين استجابوا لله والرسول من بعد ما أصابهم القرح","r":[3,172,175],"n":"ثبات المؤمنين بعد الجراح، واستجابتهم، وقولهم: حسبنا الله ونعم الوكيل."}],"q":[{"w":"السعدي","bk":"saadi","s":3,"ay":172,"x":"لما رجع النبي - صلى الله عليه وسلم - من أحد إلى المدينة وسمع أن أبا سفيان ومن معه من المشركين قد هموا بالرجوع إلى المدينة ندب أصحابه إلى الخروج، فخرجوا على ما بهم من الجراح استجابة لله ولرسوله وطاعة لله ولرسوله، فوصلوا إلى حمراء الأسد ، وجاءهم من جاءهم وقال لهم:{إن الناس قد جمعوا لكم}؛ وهمُّوا باستئصالكم تخويفاً لهم وترهيباً، فلم يزدهم ذلك إلا إيماناً بالله واتكالاً عليه {وقالوا حسبنا الله}؛ أي: كافينا كل ما أهمنا {ونعم الوكيل}؛ المفوض إليه تدبير عباده والقائم بمصالحهم"}],"h":[{"t":"حديث عائشة في الذين استجابوا","x":"{الَّذِينَ اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ مِنْ بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ لِلَّذِينَ أَحْسَنُوا مِنْهُمْ وَاتَّقَوْا أَجْرٌ عَظِيمٌ} قَالَتْ لِعُرْوَةَ يَا ابْنَ أُخْتِي كَانَ أَبُوكَ مِنْهُمُ الزُّبَيْرُ وَأَبُو بَكْرٍ، لَمَّا أَصَابَ رَسُولَ اللَّهِ صلى الله عليه وسلم مَا أَصَابَ يَوْمَ أُحُدٍ، وَانْصَرَفَ عَنْهُ الْمُشْرِكُونَ خَافَ أَنْ يَرْجِعُوا قَالَ \" مَنْ يَذْهَبُ فِي إِثْرِهِمْ \". فَانْتَدَبَ مِنْهُمْ سَبْعُونَ رَجُلاً، قَالَ كَانَ فِيهِمْ أَبُو بَكْرٍ وَالزُّبَيْرُ","src":[["bukhari","4077"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تخبر عائشة أن النبي ﷺ لما انصرف المشركون يوم أحد خاف أن يرجعوا، فانتدب سبعين رجلاً منهم أبو بكر والزبير.","te":"The hadith of ‘A’ishah on those who responded","fe":"‘A’ishah says that when the idolaters withdrew on the day of Uhud the Prophet ﷺ feared they would return, so seventy men, among them Abu Bakr and az-Zubayr, volunteered to pursue them.","en":"(Those who responded to Allah and the Messenger after injury had afflicted them — for those who did good among them and feared Allah is a great reward.) She said to ‘Urwah: O son of my sister, your father was one of them — az-Zubayr and Abu Bakr. When the Messenger of Allah ﷺ suffered what he suffered on the day of Uhud and the idolaters left, he feared they would return and said: Who will go after them? Seventy men volunteered; Abu Bakr and az-Zubayr were among them."},{"t":"حديث ابن عباس: حسبنا الله ونعم الوكيل","x":"{حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عَلَيْهِ السَّلاَمُ حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا {إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ}","src":[["bukhari","4563"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يبيّن ابن عباس أن هذه الكلمة قالها إبراهيم عليه السلام حين أُلقي في النار، وقالها محمد ﷺ حين خُوّف بجموع المشركين.","te":"The hadith of Ibn ‘Abbas: “Allah is sufficient for us”","fe":"Ibn ‘Abbas explains that these words were said by Ibrahim, peace be upon him, when he was thrown into the fire, and by Muhammad ﷺ when he was frightened with the gatherings of the idolaters.","en":"(Allah is sufficient for us, and He is the best Disposer of affairs) was said by Ibrahim, peace be upon him, when he was thrown into the fire, and was said by Muhammad ﷺ when they said: (Indeed, the people have gathered against you, so fear them. But it only increased them in faith, and they said: Allah is sufficient for us, and He is the best Disposer of affairs)."}]},{"id":"riqa","ph":"madina","t":"ذات الرقاع وصلاة الخوف","dt":"اختُلف في وقتها: قبل الخندق عند جمهور أهل المغازي، وبعده عند البخاري","s":"في ذات الرقاع صلّى النبي ﷺ بأصحابه صلاة الخوف والعدو قريب، فنزلت صفتها في سورة النساء، وصارت أصلاً في أن الصلاة في جماعة لا تسقط عن المسلمين حتى في ساحة القتال.","ay":[{"t":"وإذا كنت فيهم فأقمت لهم الصلاة","r":[4,102,102],"n":"صفة صلاة الخوف جماعة، تقوم طائفة معه وأخرى تحرس."}],"q":[{"w":"ابن كثير","bk":"ibnkathir","s":4,"ay":102,"x":"ذَاتَ الرِّقَاع كَانَتْ قَبْلَ الْخَنْدَقِ فِي قَوْلِ جُمْهُورِ عُلَمَاءِ السِّيَرِ وَالْمَغَازِي. وَمِمَّنْ نَصَّ عَلَى ذَلِكَ مُحَمَّدُ بْنُ إِسْحَاقَ، وَمُوسَى بْنُ عُقْبَةَ، وَالْوَاقِدِيُّ، وَمُحَمَّدُ بْنُ سَعْدٍ كَاتِبُهُ، وَخَلِيفَةُ بْنُ خَيَّاط وَغَيْرُهُمْ وَقَالَ الْبُخَارِيُّ وَغَيْرُهُ: كَانَتْ ذَاتُ الرِّقَاعِ بَعْدَ الْخَنْدَقِ، لِحَدِيثِ أَبِي مُوسَى وَمَا قَدم إِلَّا فِي خَيْبَرَ، وَاللَّهُ أعلم"}],"h":[{"t":"حديث صالح بن خوات في صلاة الخوف","x":"عَمَّنْ شَهِدَ رَسُولَ اللَّهِ صلى الله عليه وسلم يَوْمَ ذَاتِ الرِّقَاعِ صَلَّى صَلاَةَ الْخَوْفِ أَنَّ طَائِفَةً صَفَّتْ مَعَهُ، وَطَائِفَةٌ وُجَاهَ الْعَدُوِّ، فَصَلَّى بِالَّتِي مَعَهُ رَكْعَةً، ثُمَّ ثَبَتَ قَائِمًا، وَأَتَمُّوا لأَنْفُسِهِمْ ثُمَّ انْصَرَفُوا، فَصَفُّوا وُجَاهَ الْعَدُوِّ، وَجَاءَتِ الطَّائِفَةُ الأُخْرَى فَصَلَّى بِهِمِ الرَّكْعَةَ الَّتِي بَقِيَتْ مِنْ صَلاَتِهِ، ثُمَّ ثَبَتَ جَالِسًا، وَأَتَمُّوا لأَنْفُسِهِمْ، ثُمَّ سَلَّمَ بِهِمْ","src":[["bukhari","4129"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يصف الحديث صلاة الخوف يوم ذات الرقاع: طائفة تصلي معه ركعة وطائفة تقابل العدو، ثم تتبادلان.","te":"The hadith of Salih ibn Khawwat on the prayer of fear","fe":"The hadith describes the prayer of fear on the day of Dhat ar-Riqa‘: one group prays a rak‘ah with him while another faces the enemy, then they exchange places.","en":"Salih ibn Khawwat reported from one who prayed the prayer of fear with the Messenger of Allah ﷺ on the day of Dhat ar-Riqa‘: one group formed a row with him while another faced the enemy. He prayed one rak‘ah with those who were with him, then stood still while they completed their prayer by themselves and left and formed up facing the enemy. The other group came and he prayed with them the rak‘ah that remained of his prayer, then sat still while they completed their prayer by themselves, and then he made the salam with them."}]},{"id":"khandaq","ph":"madina","t":"غزوة الخندق (الأحزاب)","dt":"شوال، السنة الخامسة للهجرة على الأشهر","s":"تحزّبت القبائل على المدينة، فأشار سلمان الفارسي بحفر الخندق، وحُوصرت المدينة أياماً حتى أرسل الله ريحاً وجنوداً لم يروها، ثم كانت غزوة بني قريظة بعدها.","ay":[{"t":"اذكروا نعمة الله عليكم إذ جاءتكم جنود","r":[33,9,9],"n":"تذكير بنعمة الله: ريح وجنود لم تروها."},{"t":"إذ جاءوكم من فوقكم ومن أسفل منكم","r":[33,10,11],"n":"وصف شدة الحصار وزلزلة المؤمنين وابتلائهم."},{"t":"ولما رأى المؤمنون الأحزاب","r":[33,22,22],"n":"ثبات المؤمنين وقولهم: هذا ما وعدنا الله ورسوله."},{"t":"وأنزل الذين ظاهروهم","r":[33,26,27],"n":"ما كان من أمر بني قريظة بعد الخندق."}],"q":[{"w":"ابن كثير","bk":"ibnkathir","s":33,"ay":9,"x":"يَقُولُ تَعَالَى مُخْبِرًا عَنْ نِعْمَتِهِ وَفَضْلِهِ وَإِحْسَانِهِ إِلَى عِبَادِهِ الْمُؤْمِنِينَ، فِي صَرْفِهِ أَعْدَاءَهُمْ وَهَزْمِهِ إِيَّاهُمْ عَامَ تَأَلَّبُوا عَلَيْهِمْ وَتَحَزَّبُوا وَذَلِكَ عَامَ الْخَنْدَقِ، وَذَلِكَ فِي شَوَّالٍ سَنَةَ خَمْسٍ مِنَ الهجرة على الصحيح الْمَشْهُورِ."},{"w":"ابن كثير","bk":"ibnkathir","s":33,"ay":26,"x":"قَدْ تَقَدَّمَ أَنَّ بَنِي قُرَيْظَةَ لَمَّا قَدِمَتْ جُنُودُ الْأَحْزَابِ، وَنَزَلُوا عَلَى الْمَدِينَةَ، نَقَضُوا مَا كَانَ بَيْنَهُمْ وَبَيْنَ رَسُولِ اللَّهِ ﷺ مِنَ الْعَهْدِ، وَكَانَ ذَلِكَ بِسِفَارَةِ حُيَيّ بْنِ أَخْطَبَ النَّضَري -لَعَنَهُ اللَّهُ -دَخَلَ حِصْنَهُمْ، وَلَمْ يَزَلْ بِسَيِّدِهِمْ كَعْبِ بْنِ أَسَدٍ حَتَّى نَقَضَ الْعَهْدَ، وَقَالَ لَهُ فِيمَا قَالَ: وَيْحَكَ، قَدْ جِئْتُكَ بِعِزِّ الدَّهْرِ، أَتَيْتُكَ بِقُرَيْشٍ وَأَحَابِيشِهَا، وَغَطَفَانَ وَأَتْبَاعِهَا، وَلَا يَزَالُونَ هَاهُنَا حَتَّى يَسْتَأْصِلُوا مُحَمَّدًا وَأَصْحَابَهُ."}],"h":[{"t":"حفر الخندق","x":"كُنَّا مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي الْخَنْدَقِ، وَهُمْ يَحْفِرُونَ، وَنَحْنُ نَنْقُلُ التُّرَابَ عَلَى أَكْتَادِنَا، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" اللَّهُمَّ لاَ عَيْشَ إِلاَّ عَيْشُ الآخِرَهْ، فَاغْفِرْ لِلْمُهَاجِرِينَ وَالأَنْصَارِ \"","src":[["bukhari","4098"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي سهل بن سعد أن الصحابة كانوا ينقلون التراب على أكتافهم والنبي ﷺ معهم يقول: اللهم لا عيش إلا عيش الآخرة.","te":"Digging the trench","fe":"Sahl ibn Sa‘d reports that the Companions carried earth on their shoulders with the Prophet ﷺ among them saying: O Allah, there is no life but the life of the Hereafter.","en":"We were with the Messenger of Allah ﷺ at the trench while they dug and we carried the earth on our backs. The Messenger of Allah ﷺ said: O Allah, there is no life but the life of the Hereafter, so forgive the Emigrants and the Helpers."},{"t":"نُصرت بالصبا","x":"نُصِرْتُ بِالصَّبَا وَأُهْلِكَتْ عَادٌ بِالدَّبُورِ","src":[["bukhari","4105"]],"gr":"صحيح: رواه البخاري","dg":"","f":"من علامات النصر في الأحزاب أن أرسل الله ريحاً على المشركين، وفي الحديث: نُصرت بالصبا وأُهلكت عاد بالدبور.","te":"I was made victorious by the east wind","fe":"One sign of victory at al-Ahzab was a wind Allah sent upon the idolaters; the hadith says: I was made victorious by the east wind and ‘Ad were destroyed by the west wind.","en":"The Prophet ﷺ said: I was made victorious by the east wind (as-saba) and ‘Ad were destroyed by the west wind (ad-dabur)."}]},{"id":"zaynab","ph":"madina","t":"إبطال التبني: زواجه ﷺ من زينب بنت جحش ونزول الحجاب","dt":"في المدينة بعد الهجرة، وفي سنة الزواج خلاف بين أهل السير","s":"كان زيد بن حارثة يُدعى زيد بن محمد حتى نزل: «ادعوهم لآبائهم»، ثم أراد الله أن يُبطل أثر التبني بالفعل كما أبطله بالقول، فتزوّج النبي ﷺ زينب بنت جحش بعد فراق زيد لها، «لكي لا يكون على المؤمنين حرج في أزواج أدعيائهم». وفي وليمة هذا الزواج نزلت آية الحجاب.","ay":[{"t":"ادعوهم لآبائهم هو أقسط عند الله","r":[33,5,5],"n":"إبطال التبني، ونسبة الأبناء إلى آبائهم."},{"t":"فلما قضى زيد منها وطرا زوجناكها","r":[33,37,37],"n":"الحكمة المعلنة: رفع الحرج عن المؤمنين في أزواج أدعيائهم."},{"t":"ما كان محمد أبا أحد من رجالكم","r":[33,40,40],"n":"ليس النبي ﷺ أبا لأحد من الرجال، بل رسول الله وخاتم النبيين."},{"t":"يا أيها الذين آمنوا لا تدخلوا بيوت النبي","r":[33,53,53],"n":"آداب دخول بيوت النبي ﷺ، ومنها الحجاب وسؤال أزواجه من وراء حجاب."}],"q":[{"w":"السعدي","bk":"saadi","s":33,"ay":37,"x":"وكان سببُ نزول هذه الآياتِ أنَّ الله تعالى أراد أن يَشْرَعَ شرعاً عامًّا للمؤمنين أنَّ الأدعياء ليسوا في حكم الأبناء حقيقةً من جميع الوجوه، وأنَّ أزواجَهم لا جُناح على مَنْ تَبَنَّاهُم نكاحهنَّ، وكان هذا من الأمور المعتادة التي لا تكاد تزولُ إلا بحادثٍ كبيرٍ، فأرادَ أن يكون هذا الشرع قولاً من رسوله وفعلاً، وإذا أراد الله أمراً؛ جعل له سبباً، فكان زيد بن حارثة يُدعى زيد بن محمد، قد تبنَّاه النبيُّ - صلى الله عليه وسلم -، فصار يُدعى إليه، حتى نزل {ادۡعوهم لآبائِهِم}؛ فقيل له: زيد بن حارثة، وكانت تحته زينب بنت جحش ابنة عمة رسول الله - صلى الله عليه وسلم -"},{"w":"ابن كثير","bk":"ibnkathir","s":33,"ay":37,"x":"ذَكَرَ ابْنُ جَرِيرٍ، وَابْنُ أَبِي حَاتِمٍ هَاهُنَا آثَارًا عَنْ بَعْضِ السَّلَفِ، رَضِيَ اللَّهُ عَنْهُمْ، أَحْبَبْنَا أن نضرب عَنْهَا صفَحا لِعَدَمِ صِحَّتِهَا فَلَا نُورِدُهَا"}],"h":[{"t":"حديث ابن عمر في نزول «ادعوهم لآبائهم»","x":"أَنَّ زَيْدَ بْنَ حَارِثَةَ، مَوْلَى رَسُولِ اللَّهِ صلى الله عليه وسلم مَا كُنَّا نَدْعُوهُ إِلاَّ زَيْدَ ابْنَ مُحَمَّدٍ حَتَّى نَزَلَ الْقُرْآنُ {ادْعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ}","src":[["bukhari","4782"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يخبر ابن عمر أنهم كانوا يدعون زيداً زيد ابن محمد حتى نزل القرآن بنسبة الأدعياء إلى آبائهم.","te":"The hadith of Ibn ‘Umar on the revelation of (Call them by their fathers)","fe":"Ibn ‘Umar reports that they used to call Zayd “Zayd ibn Muhammad” until the Qur’an came down ordering that adopted sons be named after their fathers.","en":"Zayd ibn Harithah, the freed slave of the Messenger of Allah ﷺ — we used to call him only Zayd ibn Muhammad until the Qur’an came down: (Call them by their fathers; that is more just in the sight of Allah)."},{"t":"حديث أنس في زواج زينب ونزول الحجاب","x":"لَمَّا انْقَضَتْ عِدَّةُ زَيْنَبَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِزَيْدٍ \" فَاذْكُرْهَا عَلَىَّ \" . قَالَ فَانْطَلَقَ زَيْدٌ حَتَّى أَتَاهَا وَهْىَ تُخَمِّرُ عَجِينَهَا قَالَ فَلَمَّا رَأَيْتُهَا عَظُمَتْ فِي صَدْرِي حَتَّى مَا أَسْتَطِيعُ أَنْ أَنْظُرَ إِلَيْهَا أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم ذَكَرَهَا فَوَلَّيْتُهَا ظَهْرِي وَنَكَصْتُ عَلَى عَقِبِي فَقُلْتُ يَا زَيْنَبُ أَرْسَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَذْكُرُكِ . قَالَتْ مَا أَنَا بِصَانِعَةٍ شَيْئًا حَتَّى أُوَامِرَ رَبِّي . فَقَامَتْ إِلَى مَسْجِدِهَا وَنَزَلَ الْقُرْآنُ وَجَاءَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَدَخَلَ عَلَيْهَا بِغَيْرِ إِذْنٍ","src":[["muslim","1428"]],"gr":"صحيح: رواه مسلم","dg":"","f":"يروي أنس أن النبي ﷺ أرسل زيداً يذكره لزينب بعد انقضاء عدتها، فقالت: ما أنا بصانعة شيئاً حتى أؤامر ربي، ونزل القرآن بزواجها.","te":"The hadith of Anas on the marriage of Zaynab and the hijab","fe":"Anas reports that the Prophet ﷺ sent Zayd to mention him to Zaynab after her waiting period, and she said she would do nothing until she consulted her Lord; the Qur’an then came down concerning her marriage.","en":"When the waiting period of Zaynab ended the Messenger of Allah ﷺ said to Zayd: Mention me to her. Zayd went to her while she was kneading her dough. He said: When I saw her, she became so great in my chest that I could not look at her, because the Messenger of Allah ﷺ had mentioned her, so I turned my back to her and withdrew, and said: O Zaynab, the Messenger of Allah ﷺ sends me to mention him to you. She said: I will do nothing until I consult my Lord. She stood at her place of prayer, and the Qur’an came down, and the Messenger of Allah ﷺ came and entered upon her without permission."},{"t":"حديث أنس في نزول آية الحجاب","x":"لَمَّا تَزَوَّجَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَيْنَبَ ابْنَةَ جَحْشٍ دَعَا الْقَوْمَ، فَطَعِمُوا ثُمَّ جَلَسُوا يَتَحَدَّثُونَ وَإِذَا هُوَ كَأَنَّهُ يَتَهَيَّأُ لِلْقِيَامِ فَلَمْ يَقُومُوا، فَلَمَّا رَأَى ذَلِكَ قَامَ، فَلَمَّا قَامَ قَامَ مَنْ قَامَ، وَقَعَدَ ثَلاَثَةُ نَفَرٍ فَجَاءَ النَّبِيُّ صلى الله عليه وسلم لِيَدْخُلَ فَإِذَا الْقَوْمُ جُلُوسٌ ثُمَّ إِنَّهُمْ قَامُوا، فَانْطَلَقْتُ فَجِئْتُ فَأَخْبَرْتُ النَّبِيَّ صلى الله عليه وسلم أَنَّهُمْ قَدِ انْطَلَقُوا، فَجَاءَ حَتَّى دَخَلَ، فَذَهَبْتُ أَدْخُلُ فَأَلْقَى الْحِجَابَ بَيْنِي وَبَيْنَهُ فَأَنْزَلَ اللَّهُ {يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ} الآيَةَ","src":[["bukhari","4791"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي أنس أن بعض الضيوف أطالوا الجلوس بعد وليمة زينب، فنزلت آية الحجاب.","te":"The hadith of Anas on the revelation of the verse of the hijab","fe":"Anas reports that some guests stayed long after the wedding feast of Zaynab, and the verse of the hijab came down.","en":"When the Messenger of Allah ﷺ married Zaynab bint Jahsh he invited the people; they ate and then sat talking. He seemed to be getting ready to leave, but they did not get up. When he saw that, he got up, and some of them got up, while three men remained seated. The Prophet ﷺ came to enter and found the people still sitting, then they got up and left. I went and told the Prophet ﷺ that they had gone, so he came and entered. I went to enter, but he drew the screen between him and me, and Allah revealed: (O you who have believed, do not enter the houses of the Prophet) — the verse."}]},{"id":"takhyir","ph":"madina","t":"تخيير أزواج النبي ﷺ وآيات التحريم","dt":"في المدينة، دون تحديد سنة في الصحيح","s":"اجتمعت أمهات المؤمنين على طلب النفقة، فأمر الله نبيه ﷺ أن يخيّرهن بين الدنيا وزينتها وبين الله ورسوله والدار الآخرة، فاخترن الله ورسوله. ثم عاتب الله نبيه ﷺ حين حرّم على نفسه شيئاً أحله الله له مراعاةً لخاطر بعض أزواجه، وجعل ذلك سبباً لتشريع كفارة اليمين.","ay":[{"t":"يا أيها النبي قل لأزواجك إن كنتن تردن الحياة الدنيا","r":[33,28,29],"n":"التخيير بين الدنيا وبين الله ورسوله والدار الآخرة."},{"t":"يا أيها النبي لم تحرم ما أحل الله لك","r":[66,1,4],"n":"عتاب لطيف مع المغفرة، وتشريع كفارة اليمين."}],"q":[{"w":"السعدي","bk":"saadi","s":33,"ay":28,"x":"لما اجتمع نساءُ رسول الله - صلى الله عليه وسلم - عليه في الغيرة، وطلبن منه النفقة والكسوة؛ طلبنَ منه أمراً لا يقدر عليه في كلِّ وقت، ولم يَزَلْنَ في طلبهنَّ متَّفقات وفي مرادهنَّ متعنِّتات، فشقَّ ذلك على الرسول، حتى وصلت به الحالُ إلى أنه آلى منهنَّ شهراً، فأراد الله أن يسهِّلَ الأمرَ على رسولِهِ، وأن يرفع درجةَ زوجاتِهِ، ويُذْهِبَ عنهنَّ كلَّ أمر ينقص أجرهنَّ فأمر رسولَه أن يخيِّرهنَّ ، فقال:{يا أيُّها النبيُّ قلۡ لأزواجِك إن كنتنَّ تردنَ الحياةَ الدُّنيا}؛ أي: ليس لَكُنَّ في غيرها مطلبٌ، وصرتنَّ ترضينَ لوجودها وتغضبنَ لِفَقْدِها؛ فليس لي فيكنَّ أربٌ وحاجةٌ وأنتنَّ بهذه الحال، {فتعالَيۡن أمتِّعۡكُنَّ}: شيئاً مما عندي من الدنيا، {وأسرِّحۡكُنَّ}؛ أي: أفارقكن {سراحاً جميلاً}: من دون مغاضبةٍ ولا مشاتمةٍ، بل بسعة صدرٍ وانشراح بال، قبل أن تبلغَ الحالُ إلى ما لا ينبغي"},{"w":"السعدي","bk":"saadi","s":66,"ay":1,"x":"هذا عتابٌ من الله لنبيِّه محمدٍ - صلى الله عليه وسلم - حين حرَّم على نفسه سُرِّيَّته مارية أو شُرْبَ العسل مراعاةً لخاطر بعض زوجاته في قصَّةٍ معروفة ، فأنزل الله [تعالى] هذه الآيات"}],"h":[{"t":"حديث عائشة في التخيير","x":"جَاءَهَا حِينَ أَمَرَ اللَّهُ أَنْ يُخَيِّرَ أَزْوَاجَهُ، فَبَدَأَ بِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ \" إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلاَ عَلَيْكِ أَنْ تَسْتَعْجِلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ \"، وَقَدْ عَلِمَ أَنَّ أَبَوَىَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِهِ، قَالَتْ ثُمَّ قَالَ \" إِنَّ اللَّهَ قَالَ {يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ} \". إِلَى تَمَامِ الآيَتَيْنِ فَقُلْتُ لَهُ فَفِي أَىِّ هَذَا أَسْتَأْمِرُ أَبَوَىَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ","src":[["bukhari","4785"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تروي عائشة أن النبي ﷺ بدأ بها حين أمر الله أن يخير أزواجه، فاختارت الله ورسوله والدار الآخرة.","te":"The hadith of ‘A’ishah on the choice","fe":"‘A’ishah reports that when Allah commanded that his wives be given the choice, the Prophet ﷺ began with her, and she chose Allah, His Messenger and the Hereafter.","en":"The Messenger of Allah ﷺ came to her when Allah commanded him to give his wives the choice, and he began with me. He said: I will mention a matter to you, and you need not hurry until you consult your parents. He knew that my parents would never order me to leave him. Then he said: Allah has said: (O Prophet, say to your wives…) up to the end of the two verses. I said to him: Is it about this that I should consult my parents? I want Allah, His Messenger and the home of the Hereafter."},{"t":"حديث عائشة في شرب العسل","x":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَشْرَبُ عَسَلاً عِنْدَ زَيْنَبَ ابْنَةِ جَحْشٍ وَيَمْكُثُ عِنْدَهَا فَوَاطَيْتُ أَنَا وَحَفْصَةُ عَنْ أَيَّتُنَا دَخَلَ عَلَيْهَا فَلْتَقُلْ لَهُ أَكَلْتَ مَغَافِيرَ إِنِّي أَجِدُ مِنْكَ رِيحَ مَغَافِيرَ. قَالَ لاَ وَلَكِنِّي كُنْتُ أَشْرَبُ عَسَلاً عِنْدَ زَيْنَبَ ابْنَةِ جَحْشٍ فَلَنْ أَعُودَ لَهُ وَقَدْ حَلَفْتُ لاَ تُخْبِرِي بِذَلِكِ أَحَدًا","src":[["bukhari","4912"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تروي عائشة قصة العسل عند زينب وما كان من تواطئها مع حفصة، وقول النبي ﷺ أنه لن يعود له.","te":"The hadith of ‘A’ishah on drinking honey","fe":"‘A’ishah tells the story of the honey at Zaynab’s and her agreement with Hafsah, and the Prophet’s ﷺ statement that he would not return to it.","en":"The Messenger of Allah ﷺ used to drink honey at the house of Zaynab bint Jahsh and stay with her. Hafsah and I agreed that whichever of us he entered upon should say: Have you eaten maghafir? I find the smell of maghafir on you. He said: No, but I was drinking honey at Zaynab bint Jahsh’s, and I will not do it again, and I have sworn; do not tell anyone about this."}]},{"id":"nadir","ph":"madina","t":"إجلاء بني النضير","dt":"ربيع الأول، السنة الرابعة للهجرة على قول","s":"نقضت بنو النضير عهدها وهمّوا بالغدر، فحاصرهم النبي ﷺ حتى أُجلوا إلى خيبر والشام، وفي ذلك نزلت سورة الحشر.","ay":[{"t":"هو الذي أخرج الذين كفروا من أهل الكتاب","r":[59,2,2],"n":"الإخراج بقدرة الله، وما ظنوا أنهم يخرجون ولا ظنوا أن حصونهم تمنعهم."},{"t":"ما قطعتم من لينة","r":[59,5,5],"n":"قطع نخلهم وتحريقه بإذن الله، ليخزي الفاسقين."}],"q":[],"h":[{"t":"حرق نخل بني النضير","x":"أَنَّ النَّبِيَّ صلى الله عليه وسلم حَرَّقَ نَخْلَ بَنِي النَّضِيرِ","src":[["bukhari","4032"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ذكر ابن عمر أن النبي ﷺ حرّق نخل بني النضير، وهو سبب نزول «ما قطعتم من لينة».","te":"The burning of Banu al-Nadir’s palms","fe":"Ibn Umar mentions that the Prophet ﷺ burned the palms of Banu al-Nadir, the occasion for the verse \"whatever palm tree you cut down\".","en":"The Prophet ﷺ burned the palm trees of Banu al-Nadir."}]},{"id":"muraysi","ph":"madina","t":"غزوة بني المصطلق (المريسيع) وقول المنافقين","dt":"في السنة الخامسة أو السادسة للهجرة، وفي سنتها خلاف","s":"في هذه الغزوة تبيّن نفاق عبد الله بن أبي حين قال: «لا تنفقوا على من عند رسول الله حتى ينفضوا»، و«لئن رجعنا إلى المدينة ليخرجن الأعز منها الأذل»، فنزلت سورة المنافقين تفضح قولهم، وتؤكد أن العزة لله ولرسوله وللمؤمنين.","ay":[{"t":"هم الذين يقولون لا تنفقوا على من عند رسول الله","r":[63,7,8],"n":"قول المنافقين، وبيان أن العزة لله ولرسوله وللمؤمنين."}],"q":[{"w":"السعدي","bk":"saadi","s":63,"ay":7,"x":"وذلك في غزوة المريسيع، حين صار بين بعض المهاجرين والأنصار بعض كلام كدَّرَ الخواطر؛ ظهر حينئد نفاقُ المنافقين، وتبيَّن ما في قلوبهم ، وقال كبيرهم عبدُ الله بنُ أبيِّ بنُ سلول: ما مَثَلُنا ومَثَلُ هؤلاء ـ يعني: المهاجرين ـ إلاَّ كما قال القائل: سَمِّنْ كلبك يأكلك. وقال: لئنْ رجَعْنا إلى المدينة لَيُخْرِجَنَّ الأعزُّ منها الأذلَّ؛ بزعمه أنَّه هو وإخوانه المنافقين الأعزُّون، وأنَّ رسول الله ومن اتَّبعه هم الأذلُّون، والأمر بعكس ما قال هذا المنافق، فلهذا قال تعالى:{ولله العزَّةُ ولرسوله وللمؤمنين}: فهم الأعزَّاء، والمنافقون وإخوانُهم من الكفار هم الأذلاَّء"}],"h":[{"t":"حديث زيد بن أرقم في نزول سورة المنافقين","x":"كُنْتُ فِي غَزَاةٍ فَسَمِعْتُ عَبْدَ اللَّهِ بْنَ أُبَىٍّ، يَقُولُ لاَ تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ حَتَّى يَنْفَضُّوا مِنْ حَوْلِهِ وَلَوْ رَجَعْنَا مِنْ عِنْدِهِ لَيُخْرِجَنَّ الأَعَزُّ مِنْهَا. الأَذَلَّ فَذَكَرْتُ ذَلِكَ لِعَمِّي أَوْ لِعُمَرَ فَذَكَرَهُ لِلنَّبِيِّ صلى الله عليه وسلم فَدَعَانِي فَحَدَّثْتُهُ فَأَرْسَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى عَبْدِ اللَّهِ بْنِ أُبَىٍّ وَأَصْحَابِهِ فَحَلَفُوا مَا قَالُوا فَكَذَّبَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم وَصَدَّقَهُ فَأَصَابَنِي هَمٌّ لَمْ يُصِبْنِي مِثْلُهُ قَطُّ، فَجَلَسْتُ فِي الْبَيْتِ فَقَالَ لِي عَمِّي مَا أَرَدْتَ إِلَى أَنْ كَذَّبَكَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَمَقَتَكَ. فَأَنْزَلَ اللَّهُ تَعَالَى {إِذَا جَاءَكَ الْمُنَافِقُونَ} فَبَعَثَ إِلَىَّ النَّبِيُّ صلى الله عليه وسلم فَقَرَأَ فَقَالَ إِنَّ اللَّهَ قَدْ صَدَّقَكَ يَا زَيْدُ","src":[["bukhari","4900"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي زيد بن أرقم أنه سمع كلام عبد الله بن أبي وبلّغه، فأنكر المنافقون، ثم نزلت السورة وصدّقه الله.","te":"The hadith of Zayd ibn Arqam on the revelation of Surah al-Munafiqun","fe":"Zayd ibn Arqam reports that he heard the words of ‘Abdullah ibn Ubayy and conveyed them; the hypocrites denied them, then the surah came down and Allah confirmed his account.","en":"I was on a campaign and heard ‘Abdullah ibn Ubayy say: Do not spend on those who are with the Messenger of Allah until they disband from around him, and if we return from him the more honourable will surely expel the meaner from it. I mentioned that to my uncle or to ‘Umar, who mentioned it to the Prophet ﷺ. He called me and I told him. The Messenger of Allah ﷺ sent for ‘Abdullah ibn Ubayy and his companions, and they swore they had not said it. So the Messenger of Allah ﷺ disbelieved me and believed him, and I was grieved as never before. I sat in the house and my uncle said: What did you want but that the Messenger of Allah ﷺ should disbelieve you and detest you? Then Allah revealed: (When the hypocrites come to you). The Prophet ﷺ sent for me and recited it and said: Allah has confirmed you, O Zayd."}]},{"id":"hudaybiyya","ph":"madina","t":"صلح الحديبية وبيعة الرضوان","dt":"ذو القعدة، السنة السادسة للهجرة","s":"خرج النبي ﷺ في نحو ألف وأربعمائة يريد العمرة، فصدّته قريش، وبايعه أصحابه تحت الشجرة، ثم كان الصلح، ورجع فنزلت سورة الفتح تبشّر بالفتح المبين.","ay":[{"t":"إنا فتحنا لك فتحا مبينا","r":[48,1,3],"n":"سمّى الله الصلح فتحاً مبيناً، وتضمّن مغفرة وإتمام نعمة ونصراً عزيزاً."},{"t":"لقد رضي الله عن المؤمنين إذ يبايعونك","r":[48,18,18],"n":"رضا الله عن أهل البيعة تحت الشجرة، وإنزال السكينة عليهم."},{"t":"وهو الذي كف أيديهم عنكم","r":[48,24,24],"n":"كف الله الأيدي عن الفريقين ببطن مكة بعد أن أظفرهم."},{"t":"لقد صدق الله رسوله الرؤيا","r":[48,27,27],"n":"تصديق الرؤيا بدخول المسجد الحرام آمنين."}],"q":[{"w":"ابن كثير","bk":"ibnkathir","s":48,"ay":1,"x":"فَلَمَّا نَحَرَ هَدْيَهُ حَيْثُ أُحْصِرَ، وَرَجَعَ، أَنْزَلَ اللَّهُ، عَزَّ وَجَلَّ، هَذِهِ السُّورَةَ فِيمَا كَانَ مِنْ أَمْرِهِ وَأَمْرِهِمْ، وَجَعَلَ ذَلِكَ الصُّلْحَ فَتْحًا بِاعْتِبَارِ مَا فِيهِ مِنَ الْمَصْلَحَةِ، وَمَا آلَ الْأَمْرُ إِلَيْهِ، كَمَا رُوِيَ عَنِ ابْنِ مَسْعُودٍ، رَضِيَ اللَّهُ عَنْهُ، وَغَيْرِهِ أَنَّهُ قَالَ: إِنَّكُمْ تَعُدُّونَ الْفَتْحَ فَتْحَ مَكَّةَ، وَنَحْنُ نَعُدُّ الْفَتْحَ صُلْحَ الْحُدَيْبِيَةِ."},{"w":"ابن كثير","bk":"ibnkathir","s":48,"ay":18,"x":"يُخْبِرُ تَعَالَى عَنْ رِضَاهُ عَنِ الْمُؤْمِنِينَ الَّذِينَ بَايَعُوا رَسُولَ اللَّهِ ﷺ تَحْتَ الشَّجَرَةِ، وَقَدْ تَقَدَّمَ ذِكْرُ عِدَّتِهِمْ، وَأَنَّهُمْ كَانُوا أَلْفًا وَأَرْبَعَمِائَةٍ، وأن الشجرة كانت سمرة بأرض الحديبية."}],"h":[{"t":"جابر: أنتم خير أهل الأرض","x":"قَالَ لَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم يَوْمَ الْحُدَيْبِيَةِ \" أَنْتُمْ خَيْرُ أَهْلِ الأَرْضِ \". وَكُنَّا أَلْفًا وَأَرْبَعَمِائَةٍ، وَلَوْ كُنْتُ أُبْصِرُ الْيَوْمَ لأَرَيْتُكُمْ مَكَانَ الشَّجَرَةِ","src":[["bukhari","4154"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ذكر جابر أن النبي ﷺ قال يوم الحديبية: أنتم خير أهل الأرض، وكانوا ألفاً وأربعمائة.","te":"Jabir: you are the best people on earth","fe":"Jabir mentions that the Prophet ﷺ said on the day of al-Hudaybiyyah: you are the best people on earth, and they were 1,400.","en":"The Messenger of Allah ﷺ said to us on the day of al-Hudaybiyyah: you are the best people on earth; and we were one thousand four hundred. If I could see today I would show you the place of the tree."}]},{"id":"ifk","ph":"madina","t":"حادثة الإفك وبراءة عائشة رضي الله عنها","dt":"السنة الخامسة أو السادسة للهجرة","s":"اتُّهمت أم المؤمنين عائشة رضي الله عنها زوراً بعد غزوة بني المصطلق، فصبر النبي ﷺ وأهله شهراً، ثم نزلت آيات سورة النور تبرّئها وتؤدّب المجتمع في الأعراض.","ay":[{"t":"إن الذين جاؤوا بالإفك عصبة منكم","r":[24,11,11],"n":"بداية آيات البراءة: لا تحسبوه شراً لكم بل هو خير لكم."},{"t":"لولا إذ سمعتموه ظن المؤمنون","r":[24,12,16],"n":"الأدب في سماع الشائعات: ظن الخير، وطلب البينة، وعدم التحدث بما لا علم به."},{"t":"الخبيثات للخبيثين","r":[24,26,26],"n":"قاعدة التلاؤم: الطيبات للطيبين، وبراءة بيت النبوة."}],"q":[],"h":[{"t":"عائشة: نزول براءتها","x":"وَلَكِنْ وَاللَّهِ مَا كُنْتُ أَظُنُّ أَنَّ اللَّهَ مُنْزِلٌ فِي شَأْنِي وَحْيًا يُتْلَى، وَلَشَأْنِي فِي نَفْسِي كَانَ أَحْقَرَ مِنْ أَنْ يَتَكَلَّمَ اللَّهُ فِيَّ بِأَمْرٍ يُتْلَى، وَلَكِنْ كُنْتُ أَرْجُو أَنْ يَرَى رَسُولُ اللَّهِ صلى الله عليه وسلم فِي النَّوْمِ رُؤْيَا يُبَرِّئُنِي اللَّهُ بِهَا، قَالَتْ فَوَاللَّهِ مَا رَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَلاَ خَرَجَ أَحَدٌ مِنْ أَهْلِ الْبَيْتِ حَتَّى أُنْزِلَ عَلَيْهِ، فَأَخَذَهُ مَا كَانَ يَأْخُذُهُ مِنَ الْبُرَحَاءِ حَتَّى إِنَّهُ لَيَتَحَدَّرُ مِنْهُ مِثْلُ الْجُمَانِ مِنَ الْعَرَقِ، وَهْوَ فِي يَوْمٍ شَاتٍ مِنْ ثِقَلِ الْقَوْلِ الَّذِي يُنْزَلُ عَلَيْهِ، قَالَتْ فَلَمَّا سُرِّيَ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم سُرِّيَ عَنْهُ وَهْوَ يَضْحَكُ، فَكَانَتْ أَوَّلُ كَلِمَةٍ تَكَلَّمَ بِهَا \" يَا عَائِشَةُ، أَمَّا اللَّهُ عَزَّ وَجَلَّ فَقَدْ بَرَّأَكِ \"","src":[["bukhari","4750"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تروي عائشة كيف كانت تظن أن الله سيريها رؤيا تبرئها، فنزل الوحي، وكانت أول كلمة تكلم بها النبي ﷺ: أما الله فقد برأك.","te":"Aisha: the revelation of her vindication","fe":"Aisha relates how she expected Allah to show a dream clearing her; instead revelation came, and the Prophet’s first words were: as for Allah, He has cleared you.","en":"Aisha said: by Allah I did not think Allah would reveal about me a revelation to be recited; I thought the Messenger of Allah ﷺ might see a dream in sleep that would clear me. He had not yet left when revelation came to him, and when it lifted he was smiling; the first word he said: O Aisha, as for Allah, He has declared you innocent."}]},{"id":"hatib","ph":"madina","t":"قصة حاطب بن أبي بلتعة وسورة الممتحنة","dt":"رمضان، السنة الثامنة للهجرة، قبل فتح مكة","s":"كتب حاطب إلى قريش يخبرهم ببعض أمر النبي ﷺ، فأخبر الله نبيه، فأُخذ الكتاب من المرأة التي تحمله، وعذر النبي ﷺ حاطباً لصدقه وسابقته في بدر، ونزلت أول سورة الممتحنة تنهى عن موالاة أعداء الله وتذكّر بملة إبراهيم.","ay":[{"t":"يا أيها الذين آمنوا لا تتخذوا عدوي وعدوكم أولياء","r":[60,1,2],"n":"النهي عن موالاة أعداء الله، وتحذير من عداوتهم."}],"q":[{"w":"السعدي","bk":"saadi","s":60,"ay":1,"x":"ذكَرَ كثيرٌ من المفسِّرين رحمهم الله أنَّ سبب نزول هذه الآيات الكريمات في قصَّة حاطب بن أبي بلتعة؛ حين غزا النبيُّ - صلى الله عليه وسلم - غزاة الفتح ، فكتب حاطبٌ إلى المشركين من أهل مكَّة يخبرهم بمسير رسول الله - صلى الله عليه وسلم - إليهم؛ ليتَّخِذَ بذلك يداً عندهم، لا شكًّا ونفاقاً، وأرسله مع امرأةٍ، فأُخْبِرَ النبيُّ - صلى الله عليه وسلم - بشأنه، فأرسل إلى المرأة قبل وصولها، وأخذ منها الكتاب، وعاتب حاطباً، فاعتذر بعذرٍ قبله النبيُّ - صلى الله عليه وسلم -"}],"h":[{"t":"حديث علي في قصة حاطب","x":"بَعَثَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم أَنَا وَالزُّبَيْرَ وَالْمِقْدَادَ فَقَالَ انْطَلِقُوا حَتَّى تَأْتُوا رَوْضَةَ خَاخٍ فَإِنَّ بِهَا ظَعِينَةً مَعَهَا كِتَابٌ فَخُذُوهُ مِنْهَا . فَذَهَبْنَا تَعَادَى بِنَا خَيْلُنَا حَتَّى أَتَيْنَا الرَّوْضَةَ فَإِذَا نَحْنُ بِالظَّعِينَةِ فَقُلْنَا أَخْرِجِي الْكِتَابَ فَقَالَتْ مَا مَعِي مِنْ كِتَابٍ. فَقُلْنَا لَتُخْرِجِنَّ الْكِتَابَ أَوْ لَنُلْقِيَنَّ الثِّيَابَ. فَأَخْرَجَتْهُ مِنْ عِقَاصِهَا فَأَتَيْنَا بِهِ النَّبِيَّ صلى الله عليه وسلم فَإِذَا فِيهِ مِنْ حَاطِبِ بْنِ أَبِي بَلْتَعَةَ إِلَى أُنَاسٍ مِنَ الْمُشْرِكِينَ مِمَّنْ بِمَكَّةَ يُخْبِرُهُمْ بِبَعْضِ أَمْرِ النَّبِيِّ صلى الله عليه وسلم فَقَالَ النَّبِيُّ صلى الله عليه وسلم مَا هَذَا يَا حَاطِبُ . قَالَ لاَ تَعْجَلْ عَلَىَّ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ امْرَأً مِنْ قُرَيْشٍ وَلَمْ أَكُنْ مِنْ أَنْفُسِهِمْ وَكَانَ مَنْ مَعَكَ مِنَ الْمُهَاجِرِينَ لَهُمْ قَرَابَاتٌ يَحْمُونَ بِهَا أَهْلِيهِمْ وَأَمْوَالَهُمْ بِمَكَّةَ فَأَحْبَبْتُ إِذْ فَاتَنِي مِنَ النَّسَبِ فِيهِمْ أَنْ أَصْطَنِعَ إِلَيْهِمْ يَدًا يَحْمُونَ قَرَابَتِي وَمَا فَعَلْتُ ذَلِكَ كُفْرًا وَلاَ ارْتِدَادًا عَنْ دِينِي. فَقَالَ النَّبِيُّ صلى الله عليه وسلم إِنَّهُ قَدْ صَدَقَكُمْ . فَقَالَ عُمَرُ دَعْنِي يَا رَسُولَ اللَّهِ فَأَضْرِبَ عُنُقَهُ. فَقَالَ إِنَّهُ شَهِدَ بَدْرًا وَمَا يُدْرِيكَ لَعَلَّ اللَّهَ ـ عَزَّ وَجَلَّ ـ اطَّلَعَ عَلَى أَهْلِ بَدْرٍ فَقَالَ اعْمَلُوا مَا شِئْتُمْ فَقَدْ غَفَرْتُ لَكُمْ","src":[["bukhari","4890"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي علي أن النبي ﷺ أرسله مع الزبير والمقداد لأخذ كتاب حاطب، ثم قبل عذر حاطب وذكر سابقته في بدر.","te":"The hadith of ‘Ali on the story of Hatib","fe":"‘Ali reports that the Prophet ﷺ sent him with az-Zubayr and al-Miqdad to take Hatib’s letter, then accepted Hatib’s excuse and recalled his participation at Badr.","en":"The Messenger of Allah ﷺ sent me, az-Zubayr and al-Miqdad and said: Go until you reach Rawdat Khakh, where there is a woman travelling in a litter with a letter; take it from her. We rode off swiftly until we reached the Rawdah, and there was the woman. We said: Bring out the letter. She said: I have no letter. We said: Bring out the letter or we shall strip you. She brought it out from her braids. We brought it to the Prophet ﷺ, and in it was a letter from Hatib ibn Abi Balta‘ah to some of the idolaters in Makkah informing them of some of the Prophet’s affairs. The Prophet ﷺ said: What is this, Hatib? He said: Do not be hasty with me, O Messenger of Allah. I was a man attached to Quraysh but not one of them, while those with you among the Emigrants have relatives who protect their families and property in Makkah. Since I lacked that lineage I wanted to do them a favour so that they would protect my relatives. I did not do it out of disbelief or apostasy from my religion. The Prophet ﷺ said: He has told you the truth. ‘Umar said: Let me strike off his neck, O Messenger of Allah. He said: He was present at Badr, and what do you know, perhaps Allah looked at the people of Badr and said: Do what you wish, for I have forgiven you."}]},{"id":"fath","ph":"madina","t":"فتح مكة","dt":"20 رمضان، السنة الثامنة للهجرة","s":"سار النبي ﷺ إلى مكة في عشرة آلاف بعد نقض قريش للصلح، فدخلها فاتحاً بلا قتال يُذكر، وحطّم الأصنام، وعفا عن أهلها.","ay":[{"t":"إذا جاء نصر الله والفتح","r":[110,1,3],"n":"بشرى بالنصر والفتح ودخول الناس في دين الله أفواجاً، والأمر بالتسبيح والاستغفار."},{"t":"وقل جاء الحق وزهق الباطل","r":[17,81,81],"n":"كان النبي ﷺ يرددها وهو يطعن الأصنام حول الكعبة."}],"q":[],"h":[{"t":"تحطيم الأصنام حول الكعبة","x":"دَخَلَ النَّبِيُّ صلى الله عليه وسلم مَكَّةَ يَوْمَ الْفَتْحِ وَحَوْلَ الْبَيْتِ سِتُّونَ وَثَلاَثُمِائَةِ نُصُبٍ، فَجَعَلَ يَطْعُنُهَا بِعُودٍ فِي يَدِهِ وَيَقُولُ \" جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ، جَاءَ الْحَقُّ، وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ \"","src":[["bukhari","4287"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ذكر ابن مسعود أن النبي ﷺ دخل مكة يوم الفتح وحول البيت ستون وثلاثمائة نُصُب، فجعل يطعنها بعود في يده ويقول الآية.","te":"Breaking the idols around the Kaaba","fe":"Ibn Mas‘ud mentions that the Prophet ﷺ entered Mecca on the day of the conquest with 360 idols around the House, striking them with a stick in his hand and reciting the verse.","en":"The Prophet ﷺ entered Mecca on the day of the conquest, and around the House were three hundred and sixty idols. He began poking them with a stick in his hand and saying: \"Truth has come and falsehood has vanished\" — \"Truth has come, and falsehood cannot begin or return\"."}]},{"id":"nisaa","ph":"madina","t":"مبايعة النساء","dt":"بعد الحديبية وفتح مكة، من السنة السادسة إلى الثامنة للهجرة","s":"كان النبي ﷺ يمتحن المؤمنات المهاجرات بآية الممتحنة، فمن أقرّت بشروطها قال لها: «قد بايعتك»، دون أن تمس يده يد امرأة قط، فجاء في الآية عقد المبايعة على التوحيد وترك الكبائر والطاعة بالمعروف.","ay":[{"t":"يا أيها النبي إذا جاءك المؤمنات يبايعنك","r":[60,12,12],"n":"شروط مبايعة النساء: التوحيد، وترك الكبائر، والطاعة بالمعروف."}],"q":[{"w":"السعدي","bk":"saadi","s":60,"ay":12,"x":"هذه الشروط المذكورة في هذه الآية تسمَّى مبايعة النساء، اللاتي كنَّ يبايِعْنَّ على إقامة الواجبات المشتركة التي تجب على الذُّكور والنساء في جميع الأوقات، وأما الرجال؛ فيتفاوتُ ما يلزمُهم بحسب أحوالهم ومراتبهم وما يتعيَّن عليهم، فكان النبيُّ - صلى الله عليه وسلم - يمتثل ما أمره الله [به]، فكان إذا جاءته النساءُ يبايِعْنَه والتزمن بهذه الشروط؛ بايَعَهُنَّ وجَبَرَ قلوبَهُنَّ، واستغفر لهنَّ الله فيما يحصل منهنَّ من التقصير وأدخلهنَّ في جملة المؤمنين"}],"h":[{"t":"حديث عائشة في مبايعة النساء","x":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَمْتَحِنُ مَنْ هَاجَرَ إِلَيْهِ مِنَ الْمُؤْمِنَاتِ بِهَذِهِ الآيَةِ، بِقَوْلِ اللَّهِ {يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ} إِلَى قَوْلِهِ {غَفُورٌ رَحِيمٌ}. قَالَ عُرْوَةُ قَالَتْ عَائِشَةُ فَمَنْ أَقَرَّ بِهَذَا الشَّرْطِ مِنَ الْمُؤْمِنَاتِ قَالَ لَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم قَدْ بَايَعْتُكِ . كَلاَمًا وَلاَ وَاللَّهِ مَا مَسَّتْ يَدُهُ يَدَ امْرَأَةٍ قَطُّ فِي الْمُبَايَعَةِ، مَا يُبَايِعُهُنَّ إِلاَّ بِقَوْلِهِ قَدْ بَايَعْتُكِ عَلَى ذَلِكَ","src":[["bukhari","4891"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تروي عائشة أن النبي ﷺ كان يمتحن المؤمنات بآية الممتحنة ويبايعهن بالكلام دون مصافحة.","te":"The hadith of ‘A’ishah on the pledge of the women","fe":"‘A’ishah reports that the Prophet ﷺ tested the believing women with the verse of al-Mumtahanah and accepted their pledge verbally, without shaking hands.","en":"The Messenger of Allah ﷺ used to test the believing women who emigrated to him with this verse, in the words of Allah: (O Prophet, when the believing women come to you pledging to you) up to (Forgiving and Merciful). ‘A’ishah said: Whoever of the believing women accepted that condition, the Messenger of Allah ﷺ said to her: I have accepted your pledge — with words only. By Allah, his hand never touched the hand of a woman in the pledge; he only accepted their pledge by saying: I have accepted your pledge on that."}]},{"id":"hunayn","ph":"madina","t":"غزوة حنين","dt":"شوال، السنة الثامنة للهجرة","s":"بعد الفتح اجتمعت هوازن وثقيف، فأُعجب بعض المسلمين بكثرتهم فاضطربوا أول القتال، ثم ثبت النبي ﷺ ومن معه ونزلت السكينة وانتصروا.","ay":[{"t":"ويوم حنين إذ أعجبتكم كثرتكم","r":[9,25,26],"n":"درس عظيم: الكثرة لا تغني، والنصر من عند الله، وأنزل سكينته على رسوله وعلى المؤمنين وأنزل جنوداً لم تروها."}],"q":[],"h":[{"t":"البراء: ثبات النبي ﷺ يوم حنين","x":"يَا أَبَا عُمَارَةَ أَتَوَلَّيْتَ يَوْمَ حُنَيْنٍ فَقَالَ أَمَّا أَنَا فَأَشْهَدُ عَلَى النَّبِيِّ صلى الله عليه وسلم أَنَّهُ لَمْ يُوَلِّ، وَلَكِنْ عَجِلَ سَرَعَانُ الْقَوْمِ، فَرَشَقَتْهُمْ هَوَازِنُ، وَأَبُو سُفْيَانَ بْنُ الْحَارِثِ آخِذٌ بِرَأْسِ بَغْلَتِهِ الْبَيْضَاءِ يَقُولُ {أَنَا النَّبِيُّ لاَ كَذِبْ، أَنَا ابْنُ عَبْدِ الْمُطَّلِبْ","src":[["bukhari","4315"]],"gr":"صحيح: رواه البخاري","dg":"","f":"أنكر البراء أن النبي ﷺ ولّى يوم حنين، وذكر أنه كان يقول: أنا النبي لا كذب، أنا ابن عبد المطلب.","te":"Al-Bara’: the Prophet’s firmness at Hunayn","fe":"Al-Bara’ denied that the Prophet ﷺ turned back at Hunayn, and reported that he kept saying: I am the Prophet, no lie; I am the son of Abd al-Muttalib.","en":"A man asked al-Bara’: Abu Imara, did you flee on the day of Hunayn? He said: I testify that the Prophet ﷺ did not flee; some hasty ones rushed ahead and Hawazin showered them with arrows, while Abu Sufyan ibn al-Harith held the head of his white mule and he was saying: \"I am the Prophet, no lie; I am the son of Abd al-Muttalib.\""}]},{"id":"mubahala","ph":"madina","t":"وفد نجران والمباهلة","dt":"السنة التاسعة للهجرة على المشهور","s":"قدم وفد نصارى نجران وجادلوا في عيسى عليه السلام، فنزلت الآيات تبيّن أن مثل عيسى عند الله كمثل آدم، ودعتهم إلى المباهلة فامتنعوا وصالحوا على الجزية.","ay":[{"t":"إن مثل عيسى عند الله كمثل آدم","r":[3,59,60],"n":"بيان أن خلق عيسى بلا أب لا يقتضي الألوهية، فآدم خُلق بلا أب ولا أم."},{"t":"فمن حاجك فيه من بعد ما جاءك من العلم","r":[3,61,61],"n":"آية المباهلة: الدعوة إلى الاجتماع والابتهال بلعنة الله على الكاذبين."}],"q":[{"w":"ابن كثير","bk":"ibnkathir","s":3,"ay":61,"x":"وَكَانَ سَبَبُ نُزُولِ هَذِهِ الْمُبَاهَلَةِ وَمَا قَبْلَهَا مِنْ أَوَّلِ السُّورَةِ إِلَى هُنَا فِي وفد نجران، أن النصارى حين قَدِمُوا فَجَعَلُوا يُحَاجّون فِي عِيسَى، وَيَزْعُمُونَ فِيهِ مَا يَزْعُمُونَ مِنَ الْبُنُوَّةِ وَالْإِلَهِيَّةِ، فَأَنْزَلَ اللَّهُ صَدْرَ هَذِهِ السُّورَةِ رَدا عَلَيْهِمْ، كَمَا ذَكَرَهُ الْإِمَامُ مُحَمَّدُ بْنُ إِسْحَاقَ بْنِ يَسَار وَغَيْرُهُ."},{"w":"القرطبي","bk":"qurtubi","s":3,"ay":61,"x":"قَالَ ابْنُ عَبَّاسٍ: هُمْ أَهْلُ نَجْرَانَ: السَّيِّدُ وَالْعَاقِبُ وابن الحارث رؤساؤهم."}],"h":[{"t":"حذيفة: العاقب والسيد وامتناعهما عن الملاعنة","x":"جَاءَ الْعَاقِبُ وَالسَّيِّدُ صَاحِبَا نَجْرَانَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم يُرِيدَانِ أَنْ يُلاَعِنَاهُ، قَالَ فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ لاَ تَفْعَلْ، فَوَاللَّهِ لَئِنْ كَانَ نَبِيًّا فَلاَعَنَّا، لاَ نُفْلِحُ نَحْنُ وَلاَ عَقِبُنَا مِنْ بَعْدِنَا. قَالاَ إِنَّا نُعْطِيكَ مَا سَأَلْتَنَا، وَابْعَثْ مَعَنَا رَجُلاً أَمِينًا، وَلاَ تَبْعَثْ مَعَنَا إِلاَّ أَمِينًا. فَقَالَ \" لأَبْعَثَنَّ مَعَكُمْ رَجُلاً أَمِينًا حَقَّ أَمِينٍ \". فَاسْتَشْرَفَ لَهُ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ \" قُمْ يَا أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ \". فَلَمَّا قَامَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" هَذَا أَمِينُ هَذِهِ الأُمَّةِ \"","src":[["bukhari","4380"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ذكر حذيفة أن صاحبي نجران أراد أحدهما ملاعنته، فقال الآخر: لا تفعل، فوالله لئن كان نبياً فلاعنّا لا نفلح، ثم طلبا رجلاً أميناً.","te":"Hudhayfa: al-Aqib and al-Sayyid decline the invocation","fe":"Hudhayfa mentions that the two leaders of Najran wanted to invoke curses on him, but one said: do not, for if he is a prophet we will not prosper; they asked for a trustworthy man, and he sent Abu Ubayda.","en":"Al-Aqib and as-Sayyid, the two men of Najran, came to the Messenger of Allah ﷺ wishing to invoke curses on each other. One said to the other: do not, for by Allah if he is a prophet and we invoke curses, neither we nor our descendants will prosper. They said: we will give you what you ask; send with us a trustworthy man. He said: I will send a truly trustworthy man; then: rise, Abu Ubayda ibn al-Jarrah. He said: this is the trustworthy one of this nation."}]},{"id":"tabuk","ph":"madina","t":"غزوة تبوك وتوبة الثلاثة","dt":"رجب، السنة التاسعة للهجرة","s":"خرج النبي ﷺ إلى الروم في عسرة من الناس وشدة حر، فتخلّف المنافقون واعتذروا، وتخلّف ثلاثة من الصادقين ثم تاب الله عليهم؛ وسُمّيت «غزوة العسرة».","ay":[{"t":"انفروا خفافا وثقالا","r":[9,38,41],"n":"العتاب على التثاقل إلى الأرض والأمر بالنفير على كل حال."},{"t":"وعلى الثلاثة الذين خلفوا","r":[9,117,118],"n":"توبة الله على النبي والمهاجرين والأنصار، وعلى الثلاثة الذين خُلّفوا حتى ضاقت عليهم الأرض."}],"q":[],"h":[{"t":"أما ترضى أن تكون مني بمنزلة هارون","x":"خَرَجَ إِلَى تَبُوكَ، وَاسْتَخْلَفَ عَلِيًّا فَقَالَ أَتُخَلِّفُنِي فِي الصِّبْيَانِ وَالنِّسَاءِ قَالَ \" أَلاَ تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى إِلاَّ أَنَّهُ لَيْسَ نَبِيٌّ بَعْدِي \"","src":[["bukhari","4416"]],"gr":"صحيح: رواه البخاري","dg":"","f":"لما خرج النبي ﷺ إلى تبوك استخلف علياً على المدينة، وطمأنه بهذا القول.","te":"Are you not pleased to be to me as Aaron was to Moses?","fe":"When the Prophet ﷺ left for Tabuk he left Ali in charge of Medina and reassured him with these words.","en":"The Messenger of Allah ﷺ set out for Tabuk and left Ali in charge. Ali said: are you leaving me with the children and women? He said: are you not pleased to be to me as Aaron was to Moses, except that there is no prophet after me?"}]},{"id":"baraa","ph":"madina","t":"براءة من المشركين: حجة أبي بكر","dt":"ذو الحجة، السنة التاسعة للهجرة","s":"بعد تبوك أمّر النبي ﷺ أبا بكر على الحج في السنة التاسعة، ثم أردفه بعلي بن أبي طالب ليؤذن في الناس يوم النحر بأول سورة براءة: أن لا يحج بعد العام مشرك، ولا يطوف بالبيت عريان.","ay":[{"t":"براءة من الله ورسوله إلى الذين عاهدتم من المشركين","r":[9,1,3],"n":"إعلان البراءة، وإمهال المعاهدين أربعة أشهر، وإذان الحج الأكبر."}],"q":[{"w":"السعدي","bk":"saadi","s":9,"ay":1,"x":"أي: هذه {براءةٌ من الله} ومن {رسوله}: إلى جميع المشركين المعاهدين؛ أنَّ لهم أربعة أشهر يسيحون في الأرض على اختيارهم آمنين من المؤمنين، وبعد الأربعة الأشهر؛ فلا عهد لهم ولا ميثاق. وهذا لمن كان له عهدٌ مطلقٌ غير مقدَّر أو مقدرٌ بأربعة أشهر فأقل، أما من كان له عهد مقدَّر بزيادة على أربعة أشهر؛ فإنه يتعيَّن أن يتمَّم له عهده إذا لم يُخَفْ منه خيانة، ولم يبدأ بنقض العهد. ثم أنذر المعاهَدين في مدة عهدهم أنَّهم وإن كانوا آمنين؛ فإنهم لن يعجِزوا الله ولن يفوتوه، وأنه من استمر منهم على شركه؛ فإنه لا بدَّ أن يخزيه، فكان هذا مما يجلبهم إلى الدخول في الإسلام إلا من عاند، وأصرَّ، ولم يبال بوعيد الله"}],"h":[{"t":"حديث أبي هريرة في الأذان ببراءة","x":"بَعَثَنِي أَبُو بَكْرٍ فِي تِلْكَ الْحَجَّةِ فِي مُؤَذِّنِينَ، بَعَثَهُمْ يَوْمَ النَّحْرِ يُؤَذِّنُونَ بِمِنًى أَنْ لاَ يَحُجَّ بَعْدَ الْعَامِ مُشْرِكٌ، وَلاَ يَطُوفَ بِالْبَيْتِ عُرْيَانٌ. قَالَ حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ثُمَّ أَرْدَفَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِعَلِيِّ بْنِ أَبِي طَالِبٍ، وَأَمَرَهُ أَنْ يُؤَذِّنَ بِبَرَاءَةَ. قَالَ أَبُو هُرَيْرَةَ فَأَذَّنَ مَعَنَا عَلِيٌّ يَوْمَ النَّحْرِ فِي أَهْلِ مِنًى بِبَرَاءَةَ، وَأَنْ لاَ يَحُجَّ بَعْدَ الْعَامِ مُشْرِكٌ، وَلاَ يَطُوفَ بِالْبَيْتِ عُرْيَانٌ","src":[["bukhari","4655"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يروي أبو هريرة أنهم أذّنوا يوم النحر بمنى بأن لا يحج مشرك بعد العام ولا يطوف بالبيت عريان، وأن علياً أذّن ببراءة.","te":"The hadith of Abu Hurayrah on announcing Bara’ah","fe":"Abu Hurayrah reports that they announced at Mina on the day of sacrifice that no idolater may perform pilgrimage after that year and none may circle the House naked, and that ‘Ali announced Bara’ah.","en":"Abu Bakr sent me in that pilgrimage with a group of announcers whom he sent on the day of sacrifice to announce at Mina that no idolater may perform pilgrimage after this year and none may circle the House naked. Humayd ibn ‘Abd ar-Rahman said: Then the Messenger of Allah ﷺ sent ‘Ali ibn Abi Talib after him and ordered him to announce Bara’ah. Abu Hurayrah said: So ‘Ali announced with us on the day of sacrifice to the people of Mina Bara’ah, and that no idolater may perform pilgrimage after this year and none may circle the House naked."}]},{"id":"wada","ph":"madina","t":"حجة الوداع وإكمال الدين","dt":"ذو الحجة، السنة العاشرة للهجرة، يوم عرفة","s":"حجّ النبي ﷺ حجته الوحيدة بعد الهجرة وعلّم الأمة مناسكها وخطب بعرفة، ونزل في عشيّة عرفة قوله تعالى: «اليوم أكملت لكم دينكم».","ay":[{"t":"اليوم أكملت لكم دينكم","r":[5,3,3],"n":"إعلان كمال الدين وتمام النعمة والرضا بالإسلام ديناً."}],"q":[{"w":"ابن كثير","bk":"ibnkathir","s":5,"ay":3,"x":"وَقَالَ أَسْبَاطٌ عَنِ السُّدِّيِّ: نَزَلَتْ هَذِهِ الْآيَةُ يَوْمَ عَرَفَة، فَلَمْ يُنَزَّلْ بَعْدَهَا حَلَالٌ وَلَا حَرَامٌ، وَرَجَعَ رَسُولُ اللَّهِ ﷺ فَمَاتَ."}],"h":[{"t":"عمر: نزلت آية الإكمال بعرفة","x":"أَنَّ رَجُلاً، مِنَ الْيَهُودِ قَالَ لَهُ يَا أَمِيرَ الْمُؤْمِنِينَ، آيَةٌ فِي كِتَابِكُمْ تَقْرَءُونَهَا لَوْ عَلَيْنَا مَعْشَرَ الْيَهُودِ نَزَلَتْ لاَتَّخَذْنَا ذَلِكَ الْيَوْمَ عِيدًا. قَالَ أَىُّ آيَةٍ قَالَ {الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلاَمَ دِينًا}. قَالَ عُمَرُ قَدْ عَرَفْنَا ذَلِكَ الْيَوْمَ وَالْمَكَانَ الَّذِي نَزَلَتْ فِيهِ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ قَائِمٌ بِعَرَفَةَ يَوْمَ جُمُعَةٍ","src":[["bukhari","45"]],"gr":"صحيح: رواه البخاري","dg":"","f":"قال له رجل من اليهود: آية في كتابكم لو نزلت علينا لاتخذنا ذلك اليوم عيداً؛ فقال عمر: قد عرفنا اليوم والمكان، نزلت بعرفة يوم جمعة.","te":"Umar: the verse of completion came down at ‘Arafah","fe":"A Jewish man told him: a verse in your Book, if it had come down on us we would have taken that day as a festival; Umar said: we know the day and place — it came at ‘Arafah on a Friday.","en":"A man from the Jews said to Umar: Commander of the Believers, there is a verse in your Book that you recite; if it had been revealed to us Jews we would have taken that day as a festival. He asked: which verse? He said: \"Today I have perfected for you your religion and completed My favour upon you and approved Islam as your religion\". Umar said: we know the day and place it was revealed to the Prophet ﷺ — he was standing at ‘Arafah on a Friday."}]},{"id":"wafat","ph":"madina","t":"وفاة النبي ﷺ","dt":"ربيع الأول، السنة الحادية عشرة للهجرة","s":"توفي النبي ﷺ بعد أن بلّغ الرسالة وأدّى الأمانة، فاضطرب الناس وأنكر عمر رضي الله عنه الخبر أولاً، ثم خرج أبو بكر رضي الله عنه وتلا الآيات فثبّت الله به الأمة.","ay":[{"t":"إنك ميت وإنهم ميتون","r":[39,30,30],"n":"حقيقة الموت تعمّ الأنبياء وغيرهم."},{"t":"وما محمد إلا رسول","r":[3,144,144],"n":"الآية التي تلاها أبو بكر: محمد رسول قد خلت من قبله الرسل، أفإن مات أو قتل انقلبتم على أعقابكم؟"}],"q":[{"w":"القرطبي","bk":"qurtubi","s":3,"ay":144,"x":"وَفِي سُنَنِ ابْنِ مَاجَهْ عَنْ عَائِشَةَ قَالَتْ: لَمَّا قُبِضَ رَسُولُ اللَّهِ ﷺ وَأَبُو بَكْرٍ عِنْدَ امْرَأَتِهِ ابْنَةِ خَارِجَةَ بِالْعَوَالِي، فَجَعَلُوا يَقُولُونَ: لَمْ يَمُتِ النَّبِيُّ ﷺ إِنَّمَا هو بعض ما كان يأخذه عند الْوَحْيِ."}],"h":[{"t":"خطبة أبي بكر عند وفاة النبي ﷺ","x":"أَلاَ مَنْ كَانَ يَعْبُدُ مُحَمَّدًا صلى الله عليه وسلم فَإِنَّ مُحَمَّدًا قَدْ مَاتَ، وَمَنْ كَانَ يَعْبُدُ اللَّهَ فَإِنَّ اللَّهَ حَىٌّ لاَ يَمُوتُ. وَقَالَ {إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ} وَقَالَ {وَمَا مُحَمَّدٌ إِلاَّ رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ أَفَإِنْ مَاتَ أَوْ قُتِلَ انْقَلَبْتُمْ عَلَى أَعْقَابِكُمْ وَمَنْ يَنْقَلِبْ عَلَى عَقِبَيْهِ فَلَنْ يَضُرَّ اللَّهَ شَيْئًا وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ} قَالَ فَنَشَجَ النَّاسُ يَبْكُونَ","src":[["bukhari","3668"]],"gr":"صحيح: رواه البخاري","dg":"","f":"قال أبو بكر: من كان يعبد محمداً فإن محمداً قد مات، ومن كان يعبد الله فإن الله حي لا يموت، وتلا الآيتين فبكى الناس.","te":"Abu Bakr’s address at the Prophet’s passing","fe":"Abu Bakr said: whoever worshipped Muhammad, Muhammad has died; whoever worships Allah, Allah is Living and never dies; and he recited the two verses, and the people wept.","en":"Abu Bakr praised Allah and said: whoever worshipped Muhammad ﷺ, Muhammad has died; whoever worships Allah, Allah is Living and never dies. And he said: \"You will die and they will die\", and \"Muhammad is only a messenger; messengers passed before him…\". The people sobbed."}]}],"ay":{"148":"۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","150":"قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ","351":"إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ","352":"ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ","353":"فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ","413":"وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","415":"وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ","431":"وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ","432":"إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ","436":"وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّٰكِرِينَ","444":"وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ","446":"ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","671":"حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","1166":"وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ","1168":"إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُرۡدِفِينَ","1176":"فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","1189":"وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ","1259":"لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ كَثِيرَةٖ وَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ","1260":"ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَنزَلَ جُنُودٗا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُواْۚ وَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ","1272":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ","1273":"إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","1274":"إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ","1275":"ٱنفِرُواْ خِفَافٗا وَثِقَالٗا وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","1351":"لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ","1352":"وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","1895":"فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ","2029":"سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ","2109":"وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا","2801":"إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ","2802":"لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ","2803":"لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ","2804":"وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ","2805":"إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ","2806":"وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ","2816":"ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ","3145":"وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ","3146":"وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ","3147":"فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ","3541":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا","3542":"إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠","3543":"هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ زِلۡزَالٗا شَدِيدٗا","3554":"وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا","3558":"وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ فَرِيقٗا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقٗا","3559":"وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا","4087":"إِنَّكَ مَيِّتٞ وَإِنَّهُم مَّيِّتُونَ","4583":"إِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا","4584":"لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا","4585":"وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا","4600":"۞ لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا","4606":"وَهُوَ ٱلَّذِي كَفَّ أَيۡدِيَهُمۡ عَنكُمۡ وَأَيۡدِيَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا","4609":"لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمۡ وَمُقَصِّرِينَ لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُواْ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتۡحٗا قَرِيبًا","5127":"هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ","5130":"مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ","5495":"يَٰٓأَيُّهَا ٱلۡمُدَّثِّرُ","5496":"قُمۡ فَأَنذِرۡ","5497":"وَرَبَّكَ فَكَبِّرۡ","5498":"وَثِيَابَكَ فَطَهِّرۡ","5499":"وَٱلرُّجۡزَ فَٱهۡجُرۡ","5500":"وَلَا تَمۡنُن تَسۡتَكۡثِرُ","5501":"وَلِرَبِّكَ فَٱصۡبِرۡ","6106":"ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ","6107":"خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ","6108":"ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ","6109":"ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ","6110":"عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ","6213":"إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ","6214":"وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا","6215":"فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا","6079":"وَٱلضُّحَىٰ","6080":"وَٱلَّيۡلِ إِذَا سَجَىٰ","6081":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","6082":"وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ","6083":"وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ","6084":"أَلَمۡ يَجِدۡكَ يَتِيمٗا فَـَٔاوَىٰ","6085":"وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ","6086":"وَوَجَدَكَ عَآئِلٗا فَأَغۡنَىٰ","6090":"أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ","6091":"وَوَضَعۡنَا عَنكَ وِزۡرَكَ","6092":"ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ","6093":"وَرَفَعۡنَا لَكَ ذِكۡرَكَ","5758":"عَبَسَ وَتَوَلَّىٰٓ","5759":"أَن جَآءَهُ ٱلۡأَعۡمَىٰ","5760":"وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","5761":"أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ","5762":"أَمَّا مَنِ ٱسۡتَغۡنَىٰ","5763":"فَأَنتَ لَهُۥ تَصَدَّىٰ","5764":"وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ","5765":"وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ","5766":"وَهُوَ يَخۡشَىٰ","5767":"فَأَنتَ عَنۡهُ تَلَهَّىٰ","4846":"ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ","4847":"وَإِن يَرَوۡاْ ءَايَةٗ يُعۡرِضُواْ وَيَقُولُواْ سِحۡرٞ مُّسۡتَمِرّٞ","4848":"وَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرٖ مُّسۡتَقِرّٞ","5447":"قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرٞ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبٗا","5448":"يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا","4538":"وَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرٗا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ","4539":"قَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقٖ مُّسۡتَقِيمٖ","4540":"يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُجِرۡكُم مِّنۡ عَذَابٍ أَلِيمٖ","4541":"وَمَن لَّا يُجِبۡ دَاعِيَ ٱللَّهِ فَلَيۡسَ بِمُعۡجِزٖ فِي ٱلۡأَرۡضِ وَلَيۡسَ لَهُۥ مِن دُونِهِۦٓ أَوۡلِيَآءُۚ أُوْلَٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ","464":"ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ","465":"ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ","466":"فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ","467":"إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ","594":"وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","3537":"ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا","3569":"وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجٞ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرٗاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولٗا","3572":"مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا","3585":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا","3560":"يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحٗا جَمِيلٗا","3561":"وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا","5229":"يَٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","5230":"قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","5231":"وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ","5232":"إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَٰٓئِكَةُ بَعۡدَ ذَٰلِكَ ظَهِيرٌ","5194":"هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّواْۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ","5195":"يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ","5185":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","5186":"فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","5187":"وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ مَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّٰزِقِينَ","5150":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمۡ أَن تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدٗا فِي سَبِيلِي وَٱبۡتِغَآءَ مَرۡضَاتِيۚ تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡۚ وَمَن يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","5151":"إِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ","5161":"يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا جَآءَكَ ٱلۡمُؤۡمِنَٰتُ يُبَايِعۡنَكَ عَلَىٰٓ أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ شَيۡـٔٗا وَلَا يَسۡرِقۡنَ وَلَا يَزۡنِينَ وَلَا يَقۡتُلۡنَ أَوۡلَٰدَهُنَّ وَلَا يَأۡتِينَ بِبُهۡتَٰنٖ يَفۡتَرِينَهُۥ بَيۡنَ أَيۡدِيهِنَّ وَأَرۡجُلِهِنَّ وَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ فَبَايِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","1235":"بَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ","1236":"فَسِيحُواْ فِي ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرٖ وَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِي ٱلۡكَٰفِرِينَ","1237":"وَأَذَٰنٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِيٓءٞ مِّنَ ٱلۡمُشۡرِكِينَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُواْ بِعَذَابٍ أَلِيمٍ"},"nay":126};
